class BinaryIndexedTree
  @n:   Int32
  @bit: Array(Int64)

  def initialize(n)
    @n   = n
    @bit = Array.new(n + 1){ 0_i64 }
  end

  def sum(i)
    res = 0_i64
    while i > 0
      res += @bit[i]
      i -= ( i & -i )
    end
    res
  end

  def add(i, x)
    i += 1
    while i <= @n
      @bit[i] += x
      i += ( i & -i )
    end
  end
end

