template<typename T>
struct BIT{
private:
  vector<T> A;
  const int n;

public:
  BIT(int _n) : A(_n+1,0), n(_n){}

  T sum(int i){
    T s=0;
    while(i>0){
      s+=A[i];
      i-=i&-i;
    }
    return s;
  }

  T sum(int i,int j){
    return sum(j)-sum(i-1);
  }

  void add(int i,T x){
    while(i<=n){
      A[i]+=x;
      i+=i&-i;
    }
  } 
};

