struct BinaryIndexedTree {
private:
    int n;
    vector<T> bit;

public:
    BinaryIndexedTree(int _n) : n(_n + 1), bit(n + 1, 0){}

    T sum(int idx) {
        T s(0);
        for(int x = idx + 1; x > 0; x -= (x & -x)) s += bit[x];
        return s;
    }

    void add(int idx, T a) {
        for(int x = idx + 1; x <= n; x += (x & -x)) bit[x] += a;
    }

    T query(int l, int r) {
        return sum(r - 1) - sum(l - 1);
    }
};

