template <typename T>
struct BIT
{
private:
    vector<T> bit;
    T n;
    T sum(T x)
    {
        T ret = 0;
        while (x > 0)
        {
            ret += bit[x];
            x -= x & -x;
        }
        return ret;
    }

public:
    BIT(T n0) : bit(n0 + 1, 0), n(n0) {}
    BIT(T n0, vector<T> &A) : bit(n0 + 1, 0), n(n0)
    {
        for (int i = 1; i <= n; i++)
            bit[i] = A[i - 1];
        for (int i = 1; i < n; i++)
            bit[i + (i & -i)] += bit[i];
    }
    T sum(T l, T r)
    {
        return sum(r + 1) - sum(l);
    }
    T at(T x)
    {
        return sum(x, x);
    }
    void add(T p, T x)
    {
        T i = p + 1;
        while (i <= n)
        {
            bit[i] += x;
            i += i & -i;
        }
    }
};
