struct BIT {
private:
    vector<ll> array;
    const int N;

    //左からi番目までのSUMを得る
    ll getSUM1(int i){
        ll ret = 0;
        int lsb;
        while(i >= 1){
            ret += array[i];
            lsb = i & (-i);
            i -= lsb;
        }
        return ret;
    }

public:
    // 0として初期化
    BIT(int _N) : array(_N + 1, 0), N(_N) {}

    // 左からi番目にxを加える
    void add(int i, ll x){
        int lsb;
        while(i <= N){
            array[i] += x;
            lsb = i & (-i);
            i += lsb;
        }
    }

    //左からi番目からj番目のSUMを得る
    ll getSUM(int i, int j){
        return getSUM1(j) - getSUM1(i-1);
    }
};
