struct fenwick_tree {
  // using U = internal::to_unsigned_t<T>;
  // using U = T;
 private:
  int _n;
  std::vector<ull> data;

  ull sum(int r) {
    ull s = 0;
    while (r > 0) {
      s += data[r - 1];
      r -= r & -r;
    }
    return s;
  }

 public:
  fenwick_tree() : _n(0) {}
  fenwick_tree(int n) : _n(n), data(n) {}

  void add(int p, ll x) {
    assert(0 <= p && p < _n);
    p++;
    while (p <= _n) {
      data[p - 1] += (ull)(x);
      p += p & -p;
    }
  }

  ll sum(int l, int r) {
    assert(0 <= l && l <= r && r <= _n);
    return sum(r) - sum(l);
  }
};

