  int n, m;
  cin >> n >> m;
  fenwick<int64, N> A;
  for (int i = 1; i <= n; ++i) {
    int x;
    cin >> x;
    A.add(i, x);
  }
  while (m--) {
    int op, x, y;
    cin >> op >> x >> y;
    if (op == 0) {
      A.add(x + 1, y);
    } else {
      cout << A.query(y) - A.query(x) << '\n';
    }
  }
  return 0;
}

