using ll = int_fast64_t;
#define REP(i,b,e) for(ll i=b; i<e; i++)

struct fenwick {
	std::vector<ll> data;
	fenwick(int n): data(n+1, 0) {}

	void add(int idx, ll x){
		idx++;
		while(idx<data.size()){
			data[idx] += x;
			idx += idx & -idx;
		}
	}

	ll _sum(int idx){
		ll ret = 0;
		while(idx>0){
			ret += data[idx];
			idx -= idx & -idx;
		}
		return ret;
	}

	ll sum(int l, int r){
		return _sum(r) - _sum(l);
	}
};


