ll construct(vll &segTree,vi arr, int si, int left, int right)
{
    if(left == right)
    {
        segTree[si] = arr[right];
        return arr[right];
    }
    int mid = (left+right)/2;
    segTree[si] = construct(segTree,arr,si*2+1,left,mid) + construct(segTree,arr,si*2+2,mid+1,right);
    return segTree[si];
}

ll sumQuery(int left,int right, vll segTree,int l, int r,int index)
{
    if(right<left)
    {
        return 0;
    }
    if(right<l)
    {
        return 0;
    }
    if(left>r)
    {
        return 0;
    }
    if(l<=left && right<=r)
    {
        return segTree[index];
    }
    int mid = (left+right)/2;
    ll sum = sumQuery(left,mid,segTree,l,r,index*2+1) + sumQuery(mid+1,right,segTree,l,r,index*2+2);
    return sum;
}

void change(vll &segTree, int index, int diff, int left, int right, int cindex)
{
    if(cindex < left)
    {
        return;
    }
    if(cindex > right)
    {
        return;
    }
    segTree[index]+=diff;
    if(left!=right)
    {
        change(segTree,index*2+1,diff,left,(right+left)/2,cindex);
        change(segTree,index*2+2,diff,((right+left)/2)+1,right,cindex);
    }

}


