lint fact[3'000'000];
void fact_init(lint n, lint m = Mod) {
	if (3'000'000 <= n) return;
	fact[0] = fact[1] = 1;
	for (lint i = 2; i <= n; ++i) {
		fact[i] = i * fact[i - 1] % m;
	}
}

lint modpow(lint x, lint n, lint m = Mod) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % m;
		x = x * x % m;
		n >>= 1;
	}
	return res;
}

lint intpow(lint x, lint n) {
	lint res = 1;
	while (n > 0) {
		if (n & 1) res *= x;
		x *= x;
		n >>= 1;
	}
	return res;
}

lint comb(lint n, lint r, lint m = Mod) {
	if (r == 0 || r == n) return 1;
	lint res = fact[n] * modpow(fact[n - r], m - 2, m) % m * modpow(fact[r], m - 2, m) % m;
	return res < 0 ? res + m : res;
}

map<lint, lint> factring(lint n) {
	map<lint, lint> res;
	for (lint i = 2; i * i <= n; ++i) {
		while (n % i == 0) {
			n /= i;
			++res[i];
		}
	}
	if (n != 1) ++res[n];
	return res;
}

template<class T>
class binary_indexed_tree {
private:

	int size;
	vector<T>vec;

public:

	explicit binary_indexed_tree(int size)
		:size(size + 1)
	{
		vec.resize(size + 1);
	}

	// 1-indexed
	void add(int a, T w) {
		for (int x = a; x <= size; x += (x & -x)) vec[x] += w;
	}

	// [1, a)
	T sum(int a) const {
		T res = T();
		for (int x = a - 1; x > 0; x -= (x & -x)) res += vec[x];
		return res;
	}

	// [a, b)
	inline T sum(int a, int b) const {
		return sum(b) - sum(a);
	}

};

