template <class T>
class FenwickTree {
    vector<T> a;

public:
    FenwickTree(){};
    FenwickTree(int size) {
        a = vector<T>(size + 1, 0);
    }

    void add(int idx, T value) {
        idx++;
        while(0 <= idx && idx < a.size()){
            a[idx] += value;
            idx += idx & (-idx);
        }
    }

    int sum(int idx) {
        int ret = 0;
        idx++;
        while(idx > 0) {
            ret += a[idx];
            idx -= idx & (-idx);
        }
        return ret;
    }

    int sum(int l, int r){
        return sum(r-1) - sum(l-1);
    }
};

