struct fenwicktree {
	int n;
	vector<int> a, t;
	fenwicktree(int N) {
		n = N;
		a.clear(); t.clear();
		a.resize(N + 1 , 0);
		t.resize(N + 1, 0);
	}
public:
	void update(int x, int val) { //val is added to the xth
		x++;
		while (x <= n) {t[x] += val; x += (x & -x);}
	}
	int query(int x) {
		x++;
		int sum = 0;
		while (x > 0) {sum += t[x]; x -= (x & -x);}
		return sum;
	}
	int sum(int l, int r) {
		return query(r) - query(l - 1);
	}
};

void solve() {
	int n, q; cin >> n >> q;
	fenwicktree ans(n);
	for (int i = 0; i < n; i++) {
		int a; cin >> a;
		ans.update(i, a);
