class BIT {
  vector<long long> dat;
public:
  BIT (int n) {
    dat.resize(n+1, 0LL);
  }
  void add(int i, long long x) {
    i++;
    while (i < (int)dat.size()) {
      dat[i] += x;
      i += i & -i;
