struct BIT{
    vector<int> array;
    int n;

    BIT(int _n): array(_n+1, 0), n(_n){
    }

    // [1, i] の和、1-ind
    int sum(int i){
        int ans = 0;
        while(i != 0){
            ans += array[i];
            i -= i & (-i);
        }
        return ans;
    }

    // [i, j] の和、1-ind
    int sum(int i, int j){
        return sum(j) - sum(i-1);
    }

    // i に x を足す
    void add(int i, int x){
        while(i <= n){
            array[i] += x;
            i += i & (-i);
        }
    }
};

