template <typename T>
struct fenwick_tree {
  using F = function<T(T, T)>;
  const F f;
  vector<T> data;
  fenwick_tree(int sz, const F f) : f(f), data(sz) {}
  void add(int k, T x) {
    for (++k; k <= data.size(); k += k & -k) data[k - 1] = f(data[k - 1], x);
  }
  T sum(int k) {
    T ret = 0;
    for (; k > 0; k -= k & -k) ret = f(ret, data[k - 1]);
    return ret;
  }
};
