long long sum(int x) {
    long long sum = 0;
    for (int i = x; i; i -= lowbit(i)) sum += tr[i];
    return sum;
}

void modify(int x, int k) {
    for (int i = x; i <= n; i += lowbit(i)) tr[i] += k;
}

