void add(int pos, ll x, vector<ll> &fenw)
{
    while (pos < fenw.size())
    {
        fenw[pos] += x;
        pos |= (pos + 1);
    }
}

ll get(int pos, vector<ll> &fenw)
{
    ll res = 0;
    while (pos >= 0)
    {
        res += fenw[pos];
        pos = (pos & (pos + 1)) - 1;
    }
    return res;
}

