struct BIT {
    vector<ll> t;
    int n;

    BIT(int n) : n(n), t(n, 0) {}

    ll qry(int i) {
        ll ret = 0;
        for(; i >= 0; i = (i & (i + 1)) - 1) ret += t[i];
        return ret;
    }

    void upd(int i, ll v) {
        for(; i < n; i = i | (i + 1)) t[i] += v;
    }

    BIT(vector<ll> a) : BIT(sz(a)) {
        for (int i = 0; i < sz(a); i++) upd(i, a[i]);
    }
};

