    {
        ul ret = 0;
        while (x > 0)
        {
            ret += bit[x];
            x -= x & -x;
        }
        return ret;
    }

public:
    BIT(ui n0, vector<ul> &A) : bit(n0 + 1, 0), n(n0)
    {
        for (ui i = 1; i <= n; i++)
            bit[i] = A[i - 1];
        for (ui i = 1; i < n; i++)
            bit[i + (i & -i)] += bit[i];
    }
