template <class T>
class FenwickTree {
 public:
  FenwickTree(const std::vector<T>& data) : n_(data.size() + 1), data_(data) {
    init();
  }

  void add(int pos, T val) {
    ++pos;
    while (pos < n_) {
      node_[pos] += val;
      pos += pos & -pos;
    }
  }

  // return sum of [0, i]
  T get(int pos) {
    ++pos;
    T sum = 0;
    while (pos > 0) {
      sum += node_[pos];
      pos -= pos & -pos;
    }
    return sum;
  }


  // this code works faster
  // return sum of [l, r)
  T get(int l, int r) {
    T sum = 0;
    while (l < r) {
      sum += node_[r];
      r -= r & -r;
    }
    while (r < l) {
      sum -= node_[l];
      l -= l & -l;
    }
    return sum;
  }


  // return sum of [l, r]
  //T get(int l, int r) { return get(r) - get(l - 1); }

  // return the first k where sum of [0, k] >= val
  // use only when all element in data >= 0
  int lower_bound(T val) {
    if (val <= 0) return 0;
    int pos = 0;
    int k = 1;
    while (k < n_ - 1) k <<= 1;
    while (k > 0) {
      if (pos + k <= n_ - 1 && node_[pos + k] < val) {
        val -= node_[pos + k];
        pos += k;
      }
      k >>= 1;
    }
    return pos;
  }

 private:
  int n_;
  std::vector<T> data_;
  std::vector<T> node_;
  void init() {
    node_.assign(n_ + 1, 0);
    for (int i = 0; i < n_ - 1; ++i) add(i, data_[i]);
  }
};

