    switch (t) {
      case 0:
        int idx, x;
        std::cin >> idx >> x;
        ft.add(idx, x);
        break;
      case 1:
        int l, r;
        std::cin >> l >> r;
        std::cout << ft.query(l, r) << '\n';
        break;
    }
  }
  return 0;
}

