struct fenwick_tree {
  int _n;
  vector<T> data;
  T sum(int p) {
    T s = 0;
    for (; p > 0; p -= p & -p) {
      s += data[p - 1];
    }
    return s;
  }

 public:
  fenwick_tree() : _n(0) {}
  fenwick_tree(int n) : _n(n), data(n) {}

  void add(int p, T x) {
    for (p++; p <= _n; p += p & -p) {
      data[p - 1] += T(x);
    }
  }

  T sum(int l, int r) { return sum(r) - sum(l); }
};

