struct BIT{
    int n;
    vector<ll> a;
    BIT(const int n_):n(n_) , a(n+1){};
    void add(int i,ll x){
        for(int idx=i;idx<=n;idx += (idx & -idx))a[idx]+=x;
    }
    ll sum(int i){
        ll res=0;
        for(int idx=i;idx>0; idx -= (idx & -idx))res+=a[idx];
        return res;
    }
};

