template<typename T>
struct segment_tree {
	long long N;				// the size of V
	long long M;				// the number of leaves
	std::vector<T> V;			// Segment Tree, 1-indexed
	std::function<T(T, T)> OP;	// binary operation
	T ID;						// identity element op OP

	segment_tree(std::vector<T>& a, std::function<T(T, T)> f, T t) : OP(f), ID(t) {
		M = 1;
		while (M < a.size()) M *= 2;
		N = 2 * M;
		V.resize(N, ID);
		for (long long i = 0; i < a.size(); i++) V[M + i] = a[i];
		for (long long i = a.size(); i < M; i++) V[M + i] = ID;
		for (long long i = M - 1; i > 0; i--) {
			V[i] = OP(V[2 * i], V[2 * i + 1]);
		}
	}

	segment_tree() {}
	void init(std::vector<T>& a, std::function<T(T, T)> f, T t) {
		OP = f; ID = t;
		M = 1;
		while (M < a.size()) M *= 2;
		N = 2 * M;
		V.resize(N, ID);
		for (long long i = 0; i < a.size(); i++) V[M + i] = a[i];
		for (long long i = a.size(); i < M; i++) V[M + i] = ID;
		for (long long i = M - 1; i > 0; i--) {
			V[i] = OP(V[2 * i], V[2 * i + 1]);
		}
	}

	void point_update(long long i, T x) {
		i += M;
		V[i] = x;
		while (i / 2 < i) {
			i /= 2;
			V[i] = OP(V[2 * i], V[2 * i + 1]);
		}
	}

	T range_subfunc(
		long long cur_node, long long cur_left, long long cur_right,
		long long l, long long r
	) {
		if (cur_right <= l || r <= cur_left) return ID;
		if (l <= cur_left && cur_right <= r) return V[cur_node];
		long long mid = (cur_left + cur_right) / 2;
		return OP(
			range_subfunc(cur_node * 2, cur_left, mid, l, r),
			range_subfunc(cur_node * 2 + 1, mid, cur_right, l, r)
		);
	}

	T range_fold(long long l, long long r) {
		return range_subfunc(1, 0, M, l, r);
	}
};

