template<typename T>
struct SegmentTree {  // For Range Sum Query
  vector<T> data;
  int size = -1;

  SegmentTree(int N) {
    size = 1;
    while (size < N) size *= 2;
    data.resize(2 * size - 1, 0);
  }

  void Add(int k, T x) {
    k += size - 1;
    data[k] += x;

    while(k > 0) {
      k = (k - 1) / 2;
      data[k] = data[2 * k + 1] + data[2 * k + 2];
    }
  }

  // return value in [a, b]
  T Query(int a, int b) const { return Query(a, b + 1, 0, 0, size); }
  // return value in [a, b)
  // by searching index k node which cover [l, r) region.
  T Query(int a, int b, int k, int l, int r) const {
    // l/r is out of bound.
    if (r <= a || b <= l) return 0;

    // cover full range.
    if (a <= l && r <= b) return data[k];

    T left  = Query(a, b, 2 * k + 1, l, (l + r) /2);
    T right = Query(a, b, 2 * k + 2, (l + r) /2, r);
    return left + right;
  }

  void Print() {
    int k = 1;
    for (int i = 0; i < data.size(); ++i) {
      if (i == k) {
        k = 2 * k + 1; cout << "| ";
      }
      cout << data[i] << " ";
    }
    cout << endl;
  }
};

