// Reference: https://en.wikipedia.org/wiki/Fenwick_tree
template <class T>
struct fenwick_tree {
  using U = internal::to_unsigned_t<T>;

 public:
  fenwick_tree() : _n(0) {}
  fenwick_tree(int n) : _n(n), data(n) {}

  void add(int p, T x) {
    assert(0 <= p && p < _n);
    p++;
    while (p <= _n) {
      data[p - 1] += U(x);
      p += p & -p;
    }
  }

  T sum(int l, int r) {
    assert(0 <= l && l <= r && r <= _n);
    return sum(r) - sum(l);
  }

  int _n;
  std::vector<U> data;

  U sum(int r) {
    U s = 0;
    while (r > 0) {
      s += data[r - 1];
      r -= r & -r;
    }
    return s;
  }
};

}  // namespace atcoder

int main() {
  int N, Q;
  rd(N, Q);
  atcoder::fenwick_tree<long long> bit(N);
  for (int i = 1; i <= N; i++) {
    int n;
    rd(n);
    bit.data[i - 1] += n;
    int j = i + (i & -i);
    if (j <= N) bit.data[j - 1] += bit.data[i - 1];
  }
  for (int i = 0; i < Q; i++) {
    int x, y, z;
    rd(x, y, z);
    if (x)
      wtn(bit.sum(y, z));
    else
      bit.add(y, z);
  }
}

