template<typename T>
struct BinaryIndexedTree{
	vector<T> bit;
	BinaryIndexedTree(int sz){
		bit.resize(sz+1);
	}
	void add(int k, T x){ //k番目にxを加える
		for(int i = k; i <= bit.size(); i += i&-i) bit[i] += x;	
	}
	T sum(int k){ //[0,k)の区間の総和を求める
		T res = 0;
		for(int i = k; i > 0; i -= i&-i){
			res += bit[i];
		}
		return res;
	}
};

