ll sum(ll i, ll j) {
  j += 1;
  ll si = 0, sj = 0;
  while (i > 0) {
    si += bit.at(i);
    i -= i & -i;
  }
  while (j > 0) {
    sj += bit.at(j);
    j -= j & -j;
  }
  return sj - si;
}

void add(ll i, ll x) {
  i += 1;
  while (i <= n) {
    bit.at(i) += x;
    i += i & -i;
  }
}
