  std::vector<T> ft;

 public:
  FenwickTree(int sz) : ft(sz + 1, 0) {}

  void add(int idx, T x) {
    for (int i = idx + 1; i < static_cast<int>(ft.size()); i += i & -i) {
      ft[i] += x;
    }
  }

  T operator()(int idx) const {
    T res = 0;
    for (int i = idx + 1; i > 0; i -= i & -i) {
      res += ft[i];
    }
    return res;
  }
};

int main() {
  std::ios::sync_with_stdio(false);
  std::cin.tie(nullptr);
  int N, Q;
  std::cin >> N >> Q;
  FenwickTree<int64_t> ft(N);
  for (int i = 0; i < N; i++) {
    int a;
