    if (t == 0) {
      int idx, x;
      std::cin >> idx >> x;
      ft.add(idx, x);
    } else {
      int l, r;
      cin >> l >> r;
      std::cout << ft(r - 1) - ft(l - 1) << '\n';
    }
  }
  return 0;
}

