typedef long long ll;

struct fenwicktree {
	int n;
	vector<ll> a, t;
	fenwicktree(int N) {
		n = N;
		a.clear(); t.clear();
		a.resize(N + 1 , 0);
		t.resize(N + 1, 0);
	}
public:
	void update(int x, int val) { //val is added to the xth
		x++;
		while (x <= n) {t[x] += 1ll * val; x += (x & -x);}
	}
	ll query(int x) {
		x++;
		ll sum = 0;
		while (x > 0) {sum += 1ll * t[x]; x -= (x & -x);}
		return sum;
	}
	ll sum(int l, int r) {
		return query(r) - query(l - 1);
	}
};

void solve() {
