Int LSB(Int x) { return x & (-x); }
struct FenwickTree {
    vector<Int> A;
    FenwickTree(int n) { // [1, n]
        A.resize(n + 1);
    }
    Int sum(int idx) { // sum [1, idx]
        Int ans = 0;
        while (idx > 0) {
            ans += A[idx], idx -= LSB(idx);
        }
        return ans;
    }
    void add(int idx, Int val) { // ft[idx] += val
        while (idx < A.size()) {
            A[idx] += val, idx += LSB(idx);
        }
    }
};
