template<typename T = long long int, class Monoid_plus = std::plus<T>, T zero = 0>
class BinaryIndexedTree {
	std::vector<T> vec;
	Monoid_plus plus;
public:
	BinaryIndexedTree(const int _size) : vec(_size, zero), plus{ Monoid_plus() } {};
	BinaryIndexedTree(const int _size, const Monoid_plus& _plus) : vec(_size, zero), plus{ _plus }{};
	BinaryIndexedTree(const std::vector<T>& initial, const Monoid_plus& _plus = Monoid_plus()) : vec(initial), plus{ _plus }{
		for (auto i = 0; i < vec.size(); ++i) {
			const auto pos = i + (~i & (i + 1));
			if (pos < initial.size())
				vec[pos] += vec[i];
		}
	};
	BinaryIndexedTree(std::vector<T>&& initial, const Monoid_plus& _plus = Monoid_plus()) : vec(std::move(initial)), plus{ _plus }{
		for (auto i = 0; i < vec.size(); ++i) {
			const auto pos = i + (~i & (i + 1));
			if (pos < initial.size())
				vec[pos] += vec[i];
		}
	};
	void increase(int position, const T value) {
		while (position < vec.size()) {
			vec[position] = plus(vec[position], value);
			position += (position + 1) & ~position;
		}
	}
	T accumulate(int position) const {
		T result = zero;
		while (position >= 0) {
			result = plus(vec[position], result);
			position -= (position + 1) & ~position;
		}
		return result;
	}
	int size() const { return vec.size(); }
};
int main() {
	int n, q; std::cin >> n >> q;
	std::vector<long long int> nums(n);
	for (auto& x : nums) std::cin >> x;
	BinaryIndexedTree<> bit(nums);
	for (auto i = 0; i < q; ++i) {
		int t, l, r; std::cin >> t >> l >> r;
		if (t == 0) {
			bit.increase(l, r);
		}
		else if (t == 1) {
			std::cout << bit.accumulate(r - 1) - bit.accumulate(l - 1) << '\n';
		}
		else {
			throw 0;
		}
	}
}

