    BIT(const int n_) : n(n_) , v(n+1 , T(0)){};

    void add(const int i,const T x){
        for(int idx=i+1;idx<=n;idx+= (idx & -idx))
            v[idx]+=x;
        return;
    }
    T subsum(const int i)const{
        T res(0);
        for(int idx=i+1;idx>0;idx-=(idx & -idx))
            res+=v[idx];
        return res;
    }
    T sum(const int l,const int r)const{//[l,r)
        return subsum(r-1)-subsum(l-1);
    }
    int lower_bound(const T w)const{//よくわからなくなってるので後で直す これは1_indexedの実装のまま放置しています
        if(w<=0)return 0;
        int x=0,r=1;//xは求めるindexの一つ左を持っている
        while(r<n) r<<=1;
        for(int len=r;len>0;len=len>>1){
            if(x+len<n && v[x+len]<w){
                w-=v[x+len];
                x+=len;
            }
        }
        return x+1;
    }
};

int main(){
    ios::sync_with_stdio(false);
    std::cin.tie(nullptr);
    cout << fixed << setprecision(10);
