template <class T> struct fenwick_tree {
    using U = internal::to_unsigned_t<T>;

  public:
    fenwick_tree() : _n(0) {}
    fenwick_tree(int n) : _n(n), data(n) {}

    void add(int p, T x) {
        assert(0 <= p && p < _n);
        p++;
        while (p <= _n) {
            data[p - 1] += U(x);
            p += p & -p;
        }
    }

    T sum(int l, int r) {
        assert(0 <= l && l <= r && r <= _n);
        return sum(r) - sum(l);
    }

  private:
    int _n;
    std::vector<U> data;

    U sum(int r) {
        U s = 0;
        while (r > 0) {
            s += data[r - 1];
            r -= r & -r;
        }
        return s;
    }
};

int main(){
    int n, q; cin >> n >> q;
    fenwick_tree<long long> data(n);
    for (int i = 0; i < n; i++) {
        long long a; cin >> a;
        data.add(i,a);
    }
    while (q--) {
        int t; cin >> t;
        if (t) {
            int l, r; cin >> l >> r;
            cout << data.sum(l,r) << "\n";
        }
        else {
            int p; long long x; cin >> p >> x;
            data.add(p,x);
        }
    }
    return 0;
}

