template <class T>
class FenwickTree {
    vector<T> a;

public:
    FenwickTree(){};
    FenwickTree(int size) {
        a = vector<T>(size + 1, 0);
    }

    // 0-indexed
    void add(int idx, T value) {
        idx++;
        while(0 < idx && idx < a.size()){
            a[idx] += value;
            idx += idx & (-idx);
        }
    }

    // 1-indexed
    T sum(int idx) {
        int ret = 0;
        while(idx > 0) {
            ret += a[idx];
            idx -= idx & (-idx);
        }
        return ret;
    }

    // 0-indexed, [l, r)
    T sum(int l, int r){
        return sum(r) - sum(l);
    }
};

