class BinaryIndexedTree
{
private:
    typedef int T;
    int n;
    vector<T> data;
public:
    // コンストラクタ
    BinaryIndexedTree(int n){
        this->n = n;
        data.assign(n+1, 0);
    }
    // k番目の要素にxを加算する
    void add(int k, T x){
        ++ k;
        while(k <= n){
            data[k] += x;
            k += k & -k;
        }
    }
    // 区間[0,k)の総和を返す
    T sum(int k){
        T ret = 0;
        while(k > 0){
            ret += data[k];
            k -= k & -k;
        }
        return ret;
    }
    // 区間[a,b)の総和を返す
    T sum(int a, int b){
        return sum(b) - sum(a);
    }
};

