		if (1 == x) {
			if (0 == y) {
				cout << d.sum(z - 1) << endl;
			}
			else {
				cout << d.sum(z - 1) - d.sum(y - 1) << endl;
			}
		}
		else {
			d.add(y, z);
		}
	}
	return 0;
}

