template <class T>
struct BIT {
	vector<T> data;
	BIT(int n) {
		data.assign(n, 0);
	}

	T sum (int i) {
		T res = 0;
		while (i > 0) {
			res += data[i];
			i -= i & -i;
		}
		return res;
	}

	void add(int i, T x) {
		while (i < data.size()) {
			data[i] += x;
			i += i & -i;
		}
	}
};

int main() {
	int N, Q;
	cin >> N >> Q;
	BIT<Int> bit(N + 1);
	for (int i = 0; i < N; ++i) {
