template<class T> 
struct BinaryIndexedTree {
    int N,power = 1;
    vector<T> bit;

    BinaryIndexedTree(int N = 0): N(N){
        bit.assign(N + 1,0);
        while (power <= N) power <<= 1; //power > N
    }
    void build(const vector<T> &A) {
        for (int i = 1;i <= N; ++i) add(i,A[i - 1]);
    }
    //add x to a[i]
    void add(int i,T x) {
        for (int idx = i; idx <= N; idx += (idx & -idx)) {
            bit[idx] += x;
        }
    }
    // return a[1] + a[2] + a[3] + .. + a[k]
    T sum(int k) {
        T ret = 0;
        for (int idx = k; idx > 0; idx -= (idx & -idx)) {
            ret += bit[idx];
        }
        return ret;
    }
    // return a[l] + a[l + 1] + a[l + 2] + .. + a[r - 1]
    T sum(int l,int r) {
        return sum(r - 1) - sum(l - 1);
    }
    // return min index s.t. a[1] + a[2] + a[3] + .. + a[x] >= w
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int x = 0;
        for (int r = power; r > 0; r >>= 1) {
            if (x + r <= N && bit[x + r] < w) {
                w -= bit[x + r];
                x += r;
            }
        } 
        return x + 1;
    }
};

