template <class T> using V = vector<T>;
template <class T> using W = V<V<T>>;

template <class T> struct Fenwick {
	int n;
	V<T> seg;
	Fenwick(int _n = 0) : n(_n), seg(n + 1) {}
	// 在第i个元素上+x
	void add(int i, T x) {
		i++;
		while (i <= n) {
			seg[i] += x;
			i += i & -i;
		}
	} 
	//  [0,i)的sum
	T sum(int i) {
		T s = 0;
		while (i > 0) {
			s += seg[i];
			i -= i & -i;
		}
		return s;
	} 
	// [a, b)的sum
	T sum(int a, int b) { return sum(b) - sum(a); } 
};

