struct Fenwick
{
	vector<lli> bit;
	int n;
	Fenwick(int n)
	{
		this->n = n;
		bit.assign(n, 0);
	}
	Fenwick(vector<lli> a): Fenwick((int)a.size())
	{
		for (int i = 0; i < (int)a.size(); ++i)
			add(i, a[i]);
	}
	lli sum(int idx)
	{
		lli res = 0ll;
		for (; idx >= 0; idx = (idx & (idx + 1)) - 1)
			res += bit[idx];
		return res;
	}
	lli sum(int l, int r)
	{
		return sum(r) - sum(l - 1);
	}
	void add(int idx, int delta)
	{
		for (; idx < n; idx = idx | (idx + 1))
			bit[idx] += delta;
	}
};
int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	int n = 0, q = 0, ch = 0, p = 0, l = 0, r = 0; lli x = 0ll;
	cin >> n >> q;
	vector<lli> a(n);
	for (auto &i : a)
		cin >> i;
	Fenwick v(a);
	for (int i = 0; i < q; ++i)
	{
		cin >> ch;
