int build(int k, vector<ll> &seg){
    if(seg[k] != -1)return seg[k];
    return seg[k] =  build(2*k,seg) + build(2*k+1, seg);
}

void update(int n, int k, vector<ll>&seg, int x){
    k += n; 
    while(k>=1){
        seg[k]+=x;
        k/=2;
    }
}

ll sum(int n, int l, int r, vector<ll>&seg){
    l+=n;
    r+=n;

    r--;
    ll s = 0;
    while(l<=r){
        if(l&1){s += seg[l];l++;}
        if((r&1)==0){s += seg[r];r--;}

        l/=2;
        r/=2;
    }

    return s;
}




