template <typename T>
struct FenwickTree {  
  int n;
  vector<T> data;

  FenwickTree (int sz, T init = 0) {
    n = sz;
    data.assign(n + 1, init);
  }
  //1-indexed
  void add(int k, T x) {
    for (int i = k; i <= n; i += i & -i) data[i] += x; 
  }

  // [0, k + 1)
  T sum (int k) {
    T res = 0;
    for (int i = k; i > 0; i -= i & -i) res += data[i];
    return res;
  }
  // [l, r);
  T get (int l, int r) {
    T res = 0;
    return sum(r - 1) - sum(l - 1);
  }

  T lower_bound(T v) {
    if (v <= 0) return 0;
    T l = 0, r = 1;
    while (r < n) r <<= 1;
    for (; r > 0; r >>= 1) {
      if (l + r <= n && data[l + r] < v) {
        v -= data[l + r];
        l += r;
      }
    }
    return l + 1;
  }
};
int main() {
  int n, q;
  cin >> n >> q;
  FenwickTree<ll> bit(n);
  rep(i,n) {
    int a;
