  }

  while (q--) {
    int f;
    cin >> f;
    if (f) {
      int l, r;
      cin >> l >> r;
      cout << bit.get(l + 1, r + 1) << "\n";
    } else {
      int p, x;
      cin >> p >> x;
      bit.add(p + 1, x);
    }
  }
  return 0; 
}

