struct BIT {
    vector<int> t;
    int n;

    BIT(int n) : n(n), t(n, 0) {}

    int qry(int i) {
        int ret = 0;
        for(; i >= 0; i = (i & (i + 1)) - 1) ret += t[i];
        return ret;
    }

    void upd(int i, int v) {
        for(; i < n; i = i | (i + 1)) t[i] += v;
    }

    BIT(vector<int> a) : BIT(sz(a)) {
        for (int i = 0; i < sz(a); i++) upd(i, a[i]);
    }
};

