int bitree[555555];

int query(int x){
	int v = 0;
	while(x){
		v += bitree[x];
		x -= (x&(-x));
	}
	return v;
}

void update(int x, int v){
	++x;
	while(x<555555){
		bitree[x] += v;
		x += (x&(-x));
	}
}

