        if(x == 0){
            putchar('0');putchar(margin);return;
        }
        if(x < 0){
            putchar('-');
            x = -x;
        }
        while(x){
            *now2 = '0' + x%10;
            now2++;
            x/=10;
        }
        do{
            now2--;
            putchar(*now2);
        }while(now2 != writer);
        putchar(margin);
    }
};
