double kakudo(Dot a, Dot b1, Dot b2) {
    double size1 = kyori(a, b1), size2 = kyori(a, b2);
    double nai = (b1.x - a.x) * (b2.x - a.x) + (b1.y - a.y) * (b2.y - a.y);
    nai /= size1 * size2;
    return kodo_dosuu(acos(nai));
}

