const int SEG_LEN = 1 << 20;
vector<ll> seg(SEG_LEN * 2);

void add(int pos, ll val) {
    pos += SEG_LEN;
    seg[pos] += val;
    while (true) {
        pos /= 2;
        if (pos == 0) break;
        seg[pos] += val;
    }
}

ll sum(int l, int r) {
    l += SEG_LEN;
    r += SEG_LEN;
    ll res = 0;
    while (l < r) {
        if (l % 2) res += seg[l++];
        if (r % 2) res += seg[--r];
        l /= 2;
        r /= 2;
    }
    return res;
}

