vector<ll> seg((1LL<<20)*2,0);
void add(ll ind,ll v){
  ind+=(1LL<<20);
  seg[ind]+=v;
  while(ind!=0){
    ind/=2;
    seg[ind]=seg[2*ind]+seg[2*ind+1];
  }
}

ll sum(ll l,ll r){
  l+=(1LL<<20);
  r+=(1LL<<20);
  ll ans=0;
  while(l<r){
    if(l%2!=0){
      ans+=seg[l];
      l++;
    }
    l/=2;
    if(r%2!=0){
      ans+=seg[r-1];
      r--;
    }
    r/=2;
  }
  return ans;
}
