  void Make(){
    for (int i = 0; i < 21; i++) Tree[i].resize(1<<i);
  }
  void Add(int loc, ll val){
    for (int i = 20; i >= 0; i--){
      Tree[i][loc] += val;
      loc /= 2;
    }
  }

  ll Sum(int loc){
    ll ans = Tree[20][loc];
    int now = 20;
    while (loc > 0){
      if (loc % 2 == 0){
        loc /= 2; loc--; now--;
      }else{
        loc--;
      }
      ans += Tree[now][loc];
    }
    return ans;
  }
};

