template<typename T>
struct FenwickTree {
  int n; vector<T> d;
  FenwickTree(int n = 0) : n(n), d(n+1) {}
  void add(int i, T a = 1) { for (++i; i <= n; i += i & -i) d[i] += a; }
  T sum(int i) { T x = 0; for (; i > 0; i -= i & -i) x += d[i]; return x; }
  T sum(int l, int r) { return sum(r) - sum(l); } // [l, r)
  T operator[](const int i) { return sum(i, i+1); }
  int lower_bound(T x) { // the smallest k (0-indexed) such that sum of ft[0, k) >= x
    if (x <= 0) return 0;
    int l = 0;
    for (int i = 1<<fLog2(n); i > 0; i >>= 1) {
      if (l+i <= n && d[l+i] < x) l += i, x -= d[l];
    }
    return l+1;
  }
  int get(int k) { return lower_bound(k+1) - 1; } // the k-th (0-indexed) smallest element
};


