    void add(int m,T a){
        if(m == 0)return;
        while(m <= n){
            dat[m] += a;
            m += m & -m;
        }
    }
    T query(int m){
        T res = 0;
        if(m == 0)return res;
        while(m > 0){
            res += dat[m];
            m -= m & -m;
        }
        return res;
    }
};

