struct fenwick {
	vector<int> t;
	int n;

	fenwick(int _n) {
		n = _n;
		t.assign(n, 0);
	}
	int sum(int r) {
		int res = 0;
		for(; r >= 0; r = (r & (r + 1)) - 1) {
			res += t[r];
		}
		return res;
	}
	int sum(int l, int r) {
		return sum(r) - sum(l - 1);
	}

	void update(int pos, int delta) {
		for(; pos < n; pos = (pos | (pos + 1))) {
			t[pos] += delta;
		}
	}
};

