template <class T>
class FenwickTree {
 public:
  FenwickTree(const std::vector<T>& data) : n_(data.size() + 1), data_(data) {
    init();
  }

  void add(int pos, T val) {
    ++pos;
    while (pos < n_) {
      node_[pos] += val;
      pos += pos & -pos;
    }
  }

  // this code works faster
  // return sum of [l, r)
  T get(int l, int r) {
    T sum = 0;
    while (l < r) {
      sum += node_[r];
      r -= r & -r;
    }
    while (r < l) {
      sum -= node_[l];
      l -= l & -l;
    }
    return sum;
  }

 private:
  int n_;
  std::vector<T> data_;
  std::vector<T> node_;
  void init() {
    node_.assign(n_ + 1, 0);
    for (int i = 0; i < n_ - 1; ++i) add(i, data_[i]);
  }
};

