    BIT_tree<ll> bit(a);
    rep(i,q){
        ll c;
        cin >> c;
        if(c == 0){
            ll p,x;
            cin >> p >> x;
            bit.add(p, x);
        }else{
            ll l,r;
            cin >> l >> r;
            cout << bit.sum(l,r) << endl;
        }
    }

    return 0;
}

