struct BinaryIndexedTree{
    int N;
    vector<long long> bit;
    //全て0で初期化
    BinaryIndexedTree(int size){
        bit.resize(size+1,0);
        N=size+1;
    }
    //bit[a]に値wを加える。O(log n)
    void add(int a,long long w){
        for(int x=a;x<=N;x+=(x & -x)) bit[x]+=w;
        return;
    }
    //bit[1,a]の和bit[1]+bit[2]+   +bit[a]を求める。 O(log n)
    long long sum(int a){
        long long ret=0;
        for(int x=a;x>0;x-=(x & -x)) ret+=bit[x];
        return ret;
    }

    int lower_bound(int  w) { // a_1 + a_2 + ... + a_x >= w となるような最小の x を求め
        if (w <= 0) {
            return 0;
        } else {
            int x = 0, r = 1;
            while (r < N) r = r << 1;
            for (int len = r; len > 0; len = len >> 1) { // 長さlenは1段下るごとに半分に
                if (x + len < N && bit[x + len] < w) { // 採用するとき
                    w -= bit[x + len];
                    x += len;
                }
            }
            return x + 1;
        }
    }

};

