template<typename T = int> struct BIT{
  vector<T> node;

  int N;
  BIT(int n){
    N = n;
    node.resize(N+1);
  }

  void add(int i, T x){
    i++;
    while(i <= N){
      node[i] += x;
      i += (i & -i);
    }
  }

  T sum(int i){
    T res = 0;
    while(i > 0){
      res += node[i];
      i -= (i & -i);
    }
    return res;
  }
};
int main() {
  cin.tie(0);
  ios::sync_with_stdio(false);
  cout << fixed << setprecision(4);

  int N, Q; cin >> N >> Q;
  BIT<ll> bit(N+1);
  REP(i,N){
    ll a; cin >> a;
    bit.add(i, a);
  }

  REP(i,Q){
    int t; cin >> t;
    if(t == 0){
      int p, x; cin >> p >> x;
      bit.add(p, x);
    }else{
      int l, r; cin >> l >> r;
      cout << bit.sum(r) - bit.sum(l) << endl;
    }
  }
  return 0;
}

