    char data_in[SIZE_IN], data_out[SIZE_OUT], *p_in, *p_out, s[30];
    fast_io() { fread(data_in, 1, SIZE_IN, stdin), p_in = data_in, p_out = data_out; }
    ~fast_io() { fwrite(data_out, 1, p_out - data_out, stdout); }
    void putchar(char x) { *p_out++ = x; }
    template<typename T> void putint(T x) {
        if (x < 0) { *p_out++ = '-', x = -x; }
        int i = 0;
        do { s[i++] = x % 10 + '0'; } while (x /= 10);
        while (i--) { *p_out++ = s[i]; }
    }
    template<typename T=int> T getint() {
        while (!isdigit(*p_in) && *p_in != '-') { p_in++; }
        bool negative = *p_in == '-';
        T ret = negative ? 0 : *p_in - '0';
        while (isdigit(*++p_in)) { (ret *= 10) += *p_in - '0'; };
        return negative ? -ret : ret;
    }
} io;

template<typename M>
struct fenwick_tree {
    using T = typename M::T;
    int n;
    std::vector<T> data;
    fenwick_tree(int n) : n(n), data(n + 1, M::id()) {}
    void apply(int i, const T &x) {
        for (i++; i <= n; i += i & -i) { data[i] = M::op(data[i], x); }
    }
    T fold(int i) const {
        T ret = M::id();
        for (; i > 0; i -= i & -i) { ret = M::op(ret, data[i]); }
        return ret;
    }
    T fold(int l, int r) const { return M::op(M::inv(fold(l)), fold(r)); }
};

struct rsq {
    using T = long long;
    static T id() { return 0; }
    static T op(const T &a, const T &b) { return a + b; }
    static T inv(const T &a) { return -a; }
};

signed main() {
    int N = io.getint(), Q = io.getint();
    fenwick_tree<rsq> ft(N);
    rep(i, N) {
        int a = io.getint();
        ft.apply(i, a);
    }
    rep(i, Q) {
        int x = io.getint(), y = io.getint(), z = io.getint();
        if (x == 0) { ft.apply(y, z); }
        else { io.putint(ft.fold(y, z)), io.putchar('\n'); }
    }
}

