template <class T> struct BinaryIndexedTree {
    vector<T> data;

    BinaryIndexedTree(int sz) { data.assign(++sz, 0); }

    T sum(int k) {
        T ret = 0;
        for (++k; k > 0; k -= k & -k) ret += data[k];
        return (ret);
    }

    void add(int k, T x) {
        for (++k; k < SIZE(data); k += k & -k) data[k] += x;
    }

    // query for [l, r)
    // subtraction is required
    T query(int l, int r) { return sum(r - 1) - sum(l - 1); }
};

/* #endregion */

