template <typename T> struct BIT {
  int n;
  vector<T> bit;  // 1-indexed

  BIT() : n(-1) {}

  BIT(int n_, T d) : n(n_), bit(n_ + 1, d) {}
  // initialization2 n_要素数 d初期値

  T sum(int i) {
    T s = bit[0];
    for(int x = i + 1; x > 0; x -= (x & -x)) s += bit[x];
    return s;
  }
  // 1からiまでの和(1-indexed)

  void add(int i, T a) {
    for(int x = i + 1; x <= n; x += (x & -x)) bit[x] += a;
  }
  // iにa加える

  T lower_bound(T w) {
    if(w <= 0) return 0;
    T x = 0, r = 1;  // xは横の位置を管理するイメージ
    while(r < n) r <<= 1;
    for(T k = r; k > 0; k >>= 1) {  //上の層から見る
      if(x + k <= n && bit[x + k] < w) {
        w -= bit[x + k];
        x += k;  //右の要素に移る
      }
    }
    return x + 1;
  }
  // indまでの区間和がw以上になるような最小のindを求める
  T query(int l, int r) { return sum(r - 1) - sum(l - 1); }  // 0-index用
};

/*Binary Index Tree
区間和の取得と一点の更新が対数時間でできる
1-indexedに0を投げると何もしない*/

template <typename T>
void kukanadd(BIT<T>& p, BIT<T>& q, T w, T a, T b) {  //[a,b)にwを加算
  p.add(a, -w * a);
  p.add(b, w * b);
  q.add(a, w);
  q.add(b, -w);
}

template <typename T>
T kukansum(BIT<T>& p, BIT<T>& q, T b) {  //[0,b)の区間和を求める
  return p.sum(b) + q.sum(b) * b;
}

