        int a; cin >> a;
        seg.update(i,a);
    }
    rep(i,q) {
        int t, a, b; cin >> t >> a >> b;
        if(t) cout << seg.query(a,b) << endl;
        else seg.update(a,b);
    }
    return 0;
}

