struct BinaryIndexedTree {
	arr<int> nodes;

	BinaryIndexedTree() {
	}

	BinaryIndexedTree(int N) {
		init(N);
	}

	void init(int N) {
		nodes.init(N + 1);
	}

	void add(int index, int value) {
		for (int i = index; i < (int)nodes.size(); i |= i + 1) {
			nodes[i] += value;
		}
	}

	int sum(int index) const {
		int ret = 0;
		for (int i = index - 1; i >= 0; i = (i & (i + 1)) - 1) {
			ret += nodes[i];
		}
		return ret;
	}

	int sum(int left, int right) const {
		return sum(right) - sum(left);
	}
};

