typedef long long ll;

class FenwickTree {
private:
    vector<ll> tree;
    ll n{};

    ll cumilativeSum(ll index) {
        ll ans = 0;
        while (index >= 0) {
            ans += this->tree[index];
            decrement(index);
        }
        return ans;
    }

    static void increment(ll &index) {
        index |= (index + 1);
    }

    static void decrement(ll &index) {
        index = (index & (1 + index)) - 1;
    }

    void initializeVector(vector<ll> &v) {
        for (ll i = 0; i < n; i++) {
            this->setIndex(i, v[i]);
        }
    }

    void setSize(ll _n) {
        this->n = _n;
        this->tree.resize(_n);
    }

public:
    explicit FenwickTree(ll _n, ll initialValue = 0) {
        setSize(_n);
        fill(this->tree.begin(), this->tree.end(), initialValue);
    }

    explicit FenwickTree(ll _n, vector<ll> &initialVector) {
        setSize(_n);
        this->initializeVector(initialVector);
    }


    void incrementIndex(ll index, ll value) {
        while (index < n) {
            this->tree[index] += value;
            increment(index);
        }
    }

    void setIndex(ll index, ll value) {
        ll currentValue = this->getValueAtIndex(index);
        ll delta = value - currentValue;
        this->incrementIndex(index, delta);
    }

    void incrementRange(ll start, ll end, ll value) {
        incrementIndex(start, value);
        if (end + 1 < n) {
            incrementIndex(end + 1, -value);
        }
    }

    ll rangeSum(ll start, ll end) {
        ll sumTillEnd = this->cumilativeSum(end);
        ll sumToSubtract = this->cumilativeSum(start - 1);
        ll ans = sumTillEnd - sumToSubtract;
        return ans;
    }

    // update for range update and point query
    ll getValueAtIndex(ll index) {
        return rangeSum(index, index);
    }

};

