const int nax = 5e5+5;
vector<long long> st(nax);
int n;

void modify(int p, int v) {
	for(st[p+=n] += v;p>0;p--) st[p>>1] = st[p] + st[p^1];
}

int sum(int l, int r) {
	l+=n, r+=n;
	long long ans = 0;
	while(l<r) {
		if(l&1) ans += st[l++];
		if(r&1) ans += st[--r];
		l>>=1, r>>=1;
	}
	return ans;
}

