	for(int i = n-1;i>0;i--) st[i] = st[2*i]+st[2*i+1];
	while(q--) {
		cin >> t >> a >> b;
		if(!t) {
			modify(a, b);
		}
		else cout << sum(a, b) << endl;
	}
