template <class num_type> struct BIT {
    int n;
    vector<num_type> bit;
    num_type allsum;
    int maxbit = 1;
    BIT(int tmp) : n(tmp) {
        bit.assign(n + 1, 0);
        allsum = 0;
        while (maxbit * 2 <= n) { maxbit *= 2; }
    }

    // 初期化する
    void make_bit(auto& a) {
        for (int i = 0, sz = (int)a.size(); i < sz; i++) {
            auto v = a[i];
            auto idx = i + 1;
            allsum += v;
            while (idx < n + 1) {
                bit[idx] += v;
                idx += idx & (-idx);
            }
        }
    }

    // 位置idxに値vを足す
    void add(auto idx, auto v) {
        idx++;
        allsum += v;
        while (idx < n + 1) {
            bit[idx] += v;
            idx += idx & (-idx);
        }
    }

    // 位置0からidxまでの和(sum(bit[:idx]))を計算する
    num_type sum(auto idx) {
        num_type ret = bit[0];
        while (idx > 0) {
            ret += bit[idx];
            idx -= idx & (-idx);
        }
        return ret;
    }

    // 位置idx1からidx2までの和(sum(bit[idx1:idx2]))を計算する
    num_type sum_range(auto idx1, auto idx2) { return sum(idx2) - sum(idx1); }

    // 和がw以上となる最小のインデックスを求める
    int lowerbound(auto w) {
        if (w <= 0) { return 0; }
        int x = 0;
        int k = maxbit;
        while (k) {
            if (x + k <= n && bit[x + k] < w) {
                w -= bit[x + k];
                x += k;
            }
            k /= 2;
        }
        return x;
    }
};

