// 0-indexed
template <class T> class SegmentTree {
	int size;
	T def;
	vector<T> data;
	function<T(T, T)> f;

public:
	SegmentTree<T>(int _size, T _def, function<T(T, T)> _f) : f(_f), def(_def), size(1) {
		while (size < _size) size <<= 1;
		data = vector<T>(size * 2, def);
	}
	// bottom-up implementation
	// query for[l, r)
	T query(int l, int r) {
		T L = def, R = def;
		for (l += size, r += size; l < r; l >>= 1, r >>= 1) {
			if (l & 1) L = f(L, data[l++]);
			if (r & 1) R = f(data[--r], R);
		}
		return f(L, R);
	}
	void update(int idx, T val) {
		idx += size;
		data[idx] = val;
		while (idx > 1) {
			idx >>= 1;
			data[idx] = f(data[2 * idx], data[2 * idx + 1]);
		}
	}
	T operator[](int idx) { return data[idx + size]; }
};

class Solution {
public:
	void solve() {
		int n, q;
		cin >> n >> q;
		SegmentTree<long long> st(n, 0, [](long long l, long long r) { return l + r; });
		for (int i = 0; i < n; i++) {
			long long a;
			cin >> a;
			st.update(i, a);
		}
		while (q--) {
			int t;
			cin >> t;
			if (t == 0) {
				int i, x;
				cin >> i >> x;
				st.update(i, st[i] + x);
			} else {
				int l, r;
				cin >> l >> r;
				cout << st.query(l, r) << "\n";
			}
		}
	};
};

int main() {
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	Solution solution;
	solution.solve();
	return 0;
}

