template<typename T>
struct BIT{
	int n;
	vector<T>bit;
	BIT(int n_=0):n(n_),bit(n_+1){}
	T sum(int i)
	{
		T ans=0;
		for(;i>0;i-=i&-i)ans+=bit[i];
		return ans;
	}
	void add(int i,T a)
	{
		if(i==0)return;
		for(;i<=n;i+=i&-i)bit[i]+=a;
	}
	int lower_bound(T k)//k<=sum(ret)
	{
		if(k<=0)return 0;
		int ret=0,i=1;
		while((i<<1)<=n)i<<=1;
		for(;i;i>>=1)
			if(ret+i<=n&&bit[ret+i]<k)k-=bit[ret+=i];
		return ret+1;
	}
};
main()
{
	int N,Q;
	cin>>N>>Q;
	BIT<long>P(N);
	for(int i=0;i<N;i++)
	{
		int a;cin>>a;P.add(i+1,a);
	}
	for(int i=0;i<Q;i++)
	{
		int t,l,r;cin>>t>>l>>r;
		if(t==0)
		{
			P.add(l+1,r);
		}
		else
		{
			cout<<P.sum(r)-P.sum(l)<<endl;
		}
	}
}

