template <typename T>
void kukanadd(BIT<T>& p, BIT<T>& q, T w, T a, T b) {  //[a,b)にwを加算
  p.add0(a, -w * a);
  p.add0(b, w * b);
  q.add0(a, w);
  q.add0(b, -w);
}

template <typename T>
T kukansum(BIT<T>& p, BIT<T>& q, T b) {  //[0,b)の区間和を求める
  return p.sum0(b) + q.sum0(b) * b;
}

