struct fwtree {
    using T = i64;
    static T op(T x, T y) { return x + y; }
    static T rop(T x, T y) { return x - y; }

    int n;
    vector<T> d;

    fwtree() : n(0) {}
    fwtree(int sz) : n(sz), d(n) {}

    void add(int k, T x) {
        assert(0 <= k && k < n);
        k++;
        while (k <= n) {
            d[k - 1] = op(d[k - 1], x);
            k += k & -k;
        }
    }

    T sum(int r) {
        T s = 0;
        while (r > 0) {
            s = op(s, d[r - 1]);
            r -= r & -r;
        }
        return s;
    }

    T sum(int l, int r) {
        assert(0 <= l && l <= r && r <= n);
        return rop(sum(r), sum(l));
    }
};

