class BFenwickTree {
public:
    void solve(std::istream& in, std::ostream& out) {
        int n, q;
        in >> n >> q;
        fenwick_tree<long long> fw(n);
        for (int i = 0; i < n; ++i) {
            int a;
            in >> a;
            fw.add(i, a);
        }
        while (q--) {
            int t;
            in >> t;
            if (t) {
                int l, r;
                in >> l >> r;
                out << fw.sum(l, r) << '\n';
            } else {
                int p, x;
                in >> p >> x;
                fw.add(p, x);
            }
        }
    }
};

