struct BIT{
    int n;
    vector<int>bit;
    BIT(int x){
        n=x;
        bit.resize(n+1,0);
    }
    void add(int i,int x){
        while(i<=n){
            bit[i]+=x;
            i+=i&-i;
        }
    }
    int sum(int i){
        int res=0;
        while(i>0){
            res+=bit[i];
            i-=i&-i;
        }
        return res;
    }
    int sum(int l,int r){
        //[l,r)
        return sum(r-1)-sum(l-1);
    }
};
