//next[i][v] → 頂点 v の 2^i 先。
//next.at(i).at(j) = next.at(i - 1).at(next.at(i - 1).at(j));
int doubling(vector<vector<int>> next, int v, int N) {
	vector<signed> memo;
	ll_to_vector(2, N, memo);

	int M = 0;
	M = memo.size();  //上と下のどちらか。上の方が計算量的には有利。
	//M = next.size();

	int now = v;
	for (int i = 0; i < M; i++) {
		if (N & (int)(1LL << i)) {
			now = next.at(i).at(now);
