template<class T> class BIT   // 1-indexed (0 is not used)
{
private:
    int num;
    vector<T> bit;
public:
    BIT(int n) :bit(vector<T>(n + 1, 0)), num(n) {}

    T sum(int i) {   // sum of 1..i
        if (!i) return 0;
        return bit[i] + sum(i - (i&-i));
    }

    void add(int i, T x) {
        if (i > num) return;
        bit[i] += x;
        add(i + (i&-i), x);
    }

    int lower_bound(T x) {
        T res = 0;
        int N = 1;
        while (N < num) N *= 2;
        int i;
        for (i = N / 2; i > 0; i /= 2) {
            if (res + i < num && bit[res + i] < x) {
                x = x - bit[res + i];
                res = res + i;
            }
        }
        return res + 1;
    }
};

void solve()
{
    int n, Q;
    scanf("%d%d", &n, &Q);
    BIT<ll> bit(n);
    int i;
    for (i = 0; i < n; i++) {
