        int t, u, v;
        scanf("%d%d%d", &t, &u, &v);
        if (t == 0) {
            bit.add(u + 1, v);
        }
        else {
            printf("%lld\n", bit.sum(v) - bit.sum(u));
        }
    }

    return;
}

