void update(int idx, long long value){
    idx = idx + 1;
    while( idx<=N+1 ){
        trees[idx]+= value;
        idx += idx&(-idx);
    }
}

long long getSum(int idx){
    idx = idx + 1;
    long long  s= 0;
    while(idx > 0){
        s += trees[idx];
        idx -= idx&(-idx);
    }

    return s;
}

