struct BIT
{
    ll *tree;
    ll size;

    BIT(ll n, ll init) {
        tree = new ll[n+1];
        size = n;
        this->init(init);
    }

    void init(ll init) {
        memset(tree, 0, sizeof(ll) * (size+1));
        rep (i0, size) {
            ll idx = i0 + 1LL;
            while (idx <= size) {
                tree[idx] += init;
                idx += (idx & (-idx));
            }
        }
    }

    // idx is 1 origin
    void add(ll idx, ll x) {
        assert(idx > 0LL);
        while (idx <= size) {
            tree[idx] += x;
            idx += (idx & (-idx));
        }
    }

    // idx is 1 origin
    ll sum(ll idx) {
        assert(idx > 0LL);
        ll ret = 0LL;
        while (idx > 0LL) {
            ret += tree[idx];
            idx -= (idx & (-idx));
        }
        return ret;
    }

    // find minimum idx where sum of range [1, idx] is less or equal to border.
    // returned idx is 1 origin.
    ll lower_bound(ll border) {
        ll bitlen = 0;
        ll lsz = size;
        while (lsz) {
            bitlen++;
            lsz >>= 1LL;
        }

        ll idx = (1LL<<(bitlen-1LL));
        ll base = 0;

        for (;;) {
            bool last = ((idx & -idx) & 1LL);
            if (idx <= size && base + tree[idx] < border) {
                base += tree[idx];
                idx += ((idx & -idx) >> 1LL);
                if (last) idx++;
            }
            else {
                idx -= ((idx & -idx) >> 1LL);
            }
            if (last) return idx;
        }
    }
};


