typedef long long ll;

ll getSum(vector<ll> BITree, int index)
{
	ll sum = 0; // Iniialize result 

	// index in BITree[] is 1 more than the index in arr[] 
	index = index + 1;

	// Traverse ancestors of BITree[index] 
	while (index > 0)
	{
		// Add current element of BITree to sum 
		sum += BITree[index];

		// Move index to parent node in getSum View 
		index -= index & (-index);
	}
	return sum;
}

// Updates a node in Binary Index Tree (BITree) at given index 
// in BITree. The given value 'val' is added to BITree[i] and 
// all of its ancestors in tree. 
void updateBIT(vector<ll> &BITree, int n, int index, int val)
{
	// index in BITree[] is 1 more than the index in arr[] 
	index = index + 1;

	// Traverse all ancestors and add 'val' 
	while (index <= n)
	{
		// Add 'val' to current node of BI Tree 
		BITree[index] += val;

		// Update index to that of parent in update View 
		index += index & (-index);
	}
}

// Constructs and returns a Binary Indexed Tree for given 
// array of size n. 
vector<ll> constructBITree(int arr[], int n)
{
	// Create and initialize BITree[] as 0 
	vector<ll> BITree(n+1);
	for (int i = 1; i <= n; i++)
		BITree[i] = 0;

	// Store the actual values in BITree[] using update() 
	for (int i = 0; i < n; i++)
		updateBIT(BITree, n, i, arr[i]);

	// Uncomment below lines to see contents of BITree[] 
	//for (int i = 1; i <= n; i++)
		//cout << BITree[i] << " ";

	return BITree;
}


void solve() {
	int N, Q;
	cin >> N >> Q;
	int* arr = new int[N];

	FOR(i, 0, N - 1) {
		cin >> arr[i];
	}

	vector<ll> BITree = constructBITree(arr, N);

	while (Q--) {
		int t, a, b;
		cin >> t >> a >> b;
		if (t) {
			int sum = getSum(BITree, b - 1);

			sum -= getSum(BITree, a - 1);

			cout << sum << endl;
		}
		else {
			updateBIT(BITree, N, a, b);
		}
	}
}


int main() {
	solve();
}

