            }
        }
        pw.flush();
        pw.close();
    }

    static class FastPrintStream {
        private static final int BUF_SIZE = 1 << 15;
        private byte[] buf = new byte[BUF_SIZE];
        private int ptr = 0;

        private java.io.OutputStream out;

        public FastPrintStream(java.io.OutputStream out) {
            this.out = out;
        }

        public FastPrintStream(java.io.File file) throws java.io.IOException {
            this(new java.io.FileOutputStream(file));
        }

        public FastPrintStream(String filename) throws java.io.FileNotFoundException, java.io.IOException {
            this(new java.io.File(filename));
        }

        public FastPrintStream() {
            this(System.out);
        }

        public FastPrintStream println() {
            if (ptr == BUF_SIZE) internalFlush();
            buf[ptr++] = (byte) '\n';
            return this;
        }

        public FastPrintStream println(String s) {
            return print(s).println();
        }

        public FastPrintStream println(char[] s) {
            return print(s).println();
        }

        public FastPrintStream println(char c) {
            return print(c).println();
        }

        public FastPrintStream println(int x) {
            return print(x).println();
        }

        public FastPrintStream println(long x) {
            return print(x).println();
        }

        public FastPrintStream println(double d, int precision) {
            return print(d, precision).println();
        }

        public FastPrintStream print(String s) {
            int n = s.length();
            if (ptr + n > BUF_SIZE) {
                internalFlush();
                Block: for (int i = 0;; i += BUF_SIZE) {
                    for (int j = 0; j < BUF_SIZE; j++) {
                        if (i + j == n) break Block;
                        buf[ptr++] = (byte) s.charAt(i + j);
                    }
                    internalFlush();
                }
            } else {
                for (int i = 0; i < n; i++) {
                    buf[ptr++] = (byte) s.charAt(i);
                }
            }
            return this;
        }

        public FastPrintStream print(char[] s) {
            int n = s.length;
            if (ptr + n > BUF_SIZE) {
                internalFlush();
                Block: for (int i = 0;; i += BUF_SIZE) {
                    for (int j = 0; j < BUF_SIZE; j++) {
                        if (i + j == n) break Block;
                        buf[ptr++] = (byte) s[i + j];
                    }
                    internalFlush();
                }
            } else {
                System.arraycopy(s, 0, buf, ptr, n);
                ptr += n;
            }
            return this;
        }

        public FastPrintStream print(char c) {
            if (ptr == BUF_SIZE) internalFlush();
            buf[ptr++] = (byte) c;
            return this;
        }

        public FastPrintStream print(int x) {
            if (x == 0) {
                if (ptr == BUF_SIZE) internalFlush();
                buf[ptr++] = '0';
                return this;
            }
            int d = stringSize(x);
            if (ptr + d > BUF_SIZE) internalFlush();
            if (x < 0) {
                buf[ptr++] = '-';
                x = -x;
                d--;
            }
            int j = ptr += d; 
            while (x > 0) {
                buf[--j] = (byte) ('0' + (x % 10));
                x /= 10;
            }
            return this;
        }

        public FastPrintStream print(long x) {
            if (x == 0) {
                if (ptr == BUF_SIZE) internalFlush();
                buf[ptr++] = '0';
                return this;
            }
            int d = stringSize(x);
            if (ptr + d > BUF_SIZE) internalFlush();
            if (x < 0) {
                buf[ptr++] = '-';
                x = -x;
                d--;
            }
            int j = ptr += d; 
            while (x > 0) {
                buf[--j] = (byte) ('0' + (x % 10));
                x /= 10;
            }
            return this;
        }

        public FastPrintStream print(double d, int precision) {
            if (d < 0) {
                print('-');
                d = -d;
            }
            d += Math.pow(10, -d) / 2;
            print((long) d).print('.');
            d -= (long) d;
            for(int i = 0; i < precision; i++){
                d *= 10;
                print((int) d);
                d -= (int) d;
            }
            return this;
        }

        private void internalFlush() {
            try {
                out.write(buf, 0, ptr);
                ptr = 0;
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void flush() {
            try {
                out.write(buf, 0, ptr);
                out.flush();
                ptr = 0;
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void close() {
            try {
                out.close();
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        private static int stringSize(int x) {
            int d = 1;
            if (x >= 0) {d = 0; x = -x;}
            int p = -10;
