            if (d < 0) {
                print('-');
                d = -d;
            }
            d += Math.pow(10, -d) / 2;
            print((long) d).print('.');
            d -= (long) d;
            for(int i = 0; i < precision; i++){
                d *= 10;
                print((int) d);
                d -= (int) d;
            }
            return this;
        }

        private void internalFlush() {
            try {
                w.write(buf, 0, ptr);
                ptr = 0;
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void flush() {
            try {
                w.write(buf, 0, ptr);
                w.flush();
                ptr = 0;
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void close() {
            try {
                w.close();
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

