            return this;
        }

        public FastPrintWriter print(char c) {
            if (ptr == BUF_SIZE) flush();
            charbuf[ptr++] = c;
            return this;
        }

        public FastPrintWriter print(int x) {
            if (x == 0) {
                if (ptr == BUF_SIZE) flush();
                charbuf[ptr++] = '0';
                return this;
            }
            int d = stringSize(x);
            if (ptr + d > BUF_SIZE) flush();
            if (x < 0) {
                charbuf[ptr++] = '-';
                x = -x;
                d--;
            }
            for (int j = d - 1; j >= 0; j--) {
                int p = x / pow10i[j];
                charbuf[ptr++] = (char) ('0' + p);
                x -= p * pow10i[j];
            }
            return this;
        }

        public FastPrintWriter print(long x) {
            if (x == 0) {
                if (ptr == BUF_SIZE) flush();
                charbuf[ptr++] = '0';
                return this;
            }
            int d = stringSize(x);
            if (ptr + d > BUF_SIZE) flush();
            if (x < 0) {
                charbuf[ptr++] = '-';
                x = -x;
                d--;
            }
            for (int j = d - 1; j >= 0; j--) {
                long p = x / pow10l[j];
                charbuf[ptr++] = (char) ('0' + p);
                x -= p * pow10l[j];
            }
            return this;
        }

        public FastPrintWriter print(double d, int precision) {
            if (d < 0) {
                print('-');
                d = -d;
            }
            d += Math.pow(10, -d) / 2;
            print((long) d).print('.');
            d -= (long) d;
            for(int i = 0; i < precision; i++){
                d *= 10;
                print((int) d);
                d -= (int) d;
            }
            return this;
        }

        public void flush() {
            try {
                w.write(charbuf, 0, ptr);
                w.flush();
                ptr = 0;
            } catch (java.io.IOException e) {
                throw new RuntimeException(e);
            }
        }

        public void close() {
            try {
