public class Main {

  private static void solve() {
    int n = ni();
    int q = ni();

    long[] a = nal(n);
    long[] ft = buildFenwick(a);

    for (int i = 0; i < q; i++) {
      int t = ni();
      int x = ni();
      int y = ni();

      if (t == 0) {
        addFenwick(ft, x, y);
      } else {
        out.println(sumFenwick(ft, y - 1) - sumFenwick(ft, x - 1));
      }
    }
  }

  public static long sumFenwick(long[] ft, int i) {
    long sum = 0;
    for (i++; i > 0; i -= i & -i)
      sum += ft[i];
    return sum;
  }

  public static void addFenwick(long[] ft, int i, long v) {
    if (v == 0)
      return;
    int n = ft.length;
    for (i++; i < n; i += i & -i)
      ft[i] += v;
  }

  public static long[] buildFenwick(long[] a) {
    int n = a.length;
    long[] ft = new long[n + 1];
    System.arraycopy(a, 0, ft, 1, n);
    for (int k = 2, h = 1; k <= n; k *= 2, h *= 2) {
      for (int i = k; i <= n; i += k) {
        ft[i] += ft[i - h];
      }
    }
    return ft;
  }

