    public static class BIT{
        int n=0;
        long []a=new long[0];
        public BIT(int n){
            this.n=n;
            this.a=new long[n+1];
        }
        public void update(int pos,long val){
            for(int i=pos;i<=n;i+=(i&-i)){
                this.a[i]+=val;
            }
        }
        public long getSum(int pos){
//            if(pos==-1) return 0;
            long ans=0;
            for(int i=pos;i>0;i-=(i&-i)){
                ans+=this.a[i];
            }
            return ans;
        }
        public long sum(int left,int right){
            return getSum(right)-getSum(left);
        }
    }

