    int[] a = na(n);
    int[] ft = buildFenwick(a); 

    for (int i = 0; i <q; i ++) {
      int t = ni();
      int x = ni();
      int y = ni();

      if (t == 0) {
        addFenwick(ft, x, y);
      } else {
        out.println(sumFenwick(ft, y-1) - sumFenwick(ft, x-1));
      }
    }
  }

  public static int sumFenwick(int[] ft, int i)
	{
		int sum = 0;
		for(i++;i > 0;i -= i&-i)sum += ft[i];
		return sum;
	}

	public static void addFenwick(int[] ft, int i, int v)
	{
		if(v == 0 || i < 0)return;
		int n = ft.length;
		for(i++;i < n;i += i&-i)ft[i] += v;
	}
  public static int[] buildFenwick(int[] a)
	{
		int n = a.length;
		int[] ft = new int[n+1];
		System.arraycopy(a, 0, ft, 1, n);
		for(int k = 2, h = 1;k <= n;k*=2, h*=2){
			for(int i = k;i <= n;i+=k){
				ft[i] += ft[i-h];
			}
		}
		return ft;
	}

