	static class UnionFind
	{
		int[] par;
		int[] n_nodes;
		int max = 1;

		public UnionFind(int n)
		{
			par = new int[n];
			n_nodes = new int[n];
			for( int i=0; i<n; i++ )
			{
				par[i] = i;
				n_nodes[i] = 1;
			}
		}

		int root(int x)
		{
			if( par[x] == x ) return x;
			return par[x] = root(par[x]);
		}

		void unite(int x, int y)
		{
			int rx = root(x);
			int ry = root(y);
			if( rx == ry ) return;
			par[rx] = ry;
			n_nodes[ry] += n_nodes[rx];
			max = Math.max(max, n_nodes[ry]);
		}

		boolean same(int x, int y)
		{
			int rx = root(x);
			int ry = root(y);
			return rx == ry;
		}
	}

	static int ceilInt(int a, int b)
	{
		return (a%b==0 ? a/b : a/b+1);
	}

	static long power(long x, long n)
	{
		if( n == 0 )
		{
			return 1;
		}

		if( n % 2 == 0 )
		{
			long X = (x * x) % mod;
			return power(X, n/2);
		}
		else
		{
			return (x * power(x, n-1)) % mod;
		}
	}

