public void solve() {
	int num = ni();
	int query = ni();
	long a[] = nl(num);
	FenwickTree bit = new FenwickTree(num, a);
	for(int q = 0; q < query; q ++) {
		if(ni() == 0) bit.add(ni(), nl());
		else prtln(bit.sum(ni(), ni()));
	}
}

class FenwickTree { // N=size
	int size;
	long nodes[];
	FenwickTree(int size) { // O(N)
		this.size = size;
		nodes = new long[size];
		fill(nodes, 0);
	}
	FenwickTree(int size, long[] array) { // O(N)
		this.size = size;
		nodes = new long[size];
		fill(nodes, 0);
		for(int i = 0; i < size; i ++) add(i, array[i]);
	}

	void add(int a, long x) { // O(logN)
		a ++;
		while(a <= size) {
			nodes[a - 1] += x;
			a += a & -a;
		}
	}
	long sum(int r) { // O(logN)
		long sum = 0;
		while(r > 0) {
			sum += nodes[r - 1];
			r -= r & -r;
		}
		return sum;
	}
	long sum(int l, int r) { // O(logN)
		if(l > r) return 0;
		else return sum(r) - sum(l);
	}
}


