static class FenwickTree{
  long[] list;
  int N;
  FenwickTree(int N){
    list = new long[N];
    this.N = N;
  }

  public void add(int i, long v){
    if(v == 0){
      return;
    }
    for(i++; i <= N; i += (i & -i)){
      list[i - 1] += v;
    }
  }

  public long sum(int i){
    long sum = 0;
    for(; i > 0; i -= (i & -i)){
      sum += list[i - 1];
    }
    return sum;
  }

  //0-indexed
  public long rangeSum(int L, int R){
    return sum(R) - sum(L);
  }
}

