            int query = nextInt();
            if (query == 0) {
                int p = nextInt();
                int x = nextInt();
                t.add(p, x);
            } else {
                int l = nextInt();
                int r = nextInt();
                sb.append(t.sum(l, r)).append('\n');
            }
        }
