public class Main {
  private static final Long ZERO = Long.valueOf(0);
  private static final UpdateSingleGetRangeSegmentTree.Operator<Long> OPERATOR = new UpdateSingleGetRangeSegmentTree.Operator<>() {
    @Override
    public Long update(Long originalValue, Long argumentValue) {
      return originalValue + argumentValue;
    }

    @Override
    public Long merge(Long smallValue, Long largeValue) {
      return smallValue + largeValue;
    }

    @Override
    public Long getUnitValue() {
      return ZERO;
    }
  };

  private static List<Long> solve(int n, int q, int[] as, int[][] abcs) {
    Long[] initialValues = new Long[n];
    for (int i = 0; i < n; i++) {
      initialValues[i] = Long.valueOf(as[i]);
    }
    UpdateSingleGetRangeSegmentTree<Long> segmentTree = new UpdateSingleGetRangeSegmentTree<>(OPERATOR, initialValues);
    List<Long> answers = new ArrayList<>();
    for (int[] abc : abcs) {
      int a = abc[0];
      int b = abc[1];
      int c = abc[2];
      if (a == 0) {
        segmentTree.update(b, (long)c);
      } else {
        answers.add(segmentTree.getRange(b, c));
      }
    }
    return answers;
  }

  private static void execute(ContestReader reader, ContestWriter out) {
    int n = reader.nextInt();
    int q = reader.nextInt();
    int[] as = reader.nextInt(n);
    int[][] abcs = reader.nextInt(q, 3);
    out.printList(solve(n, q, as, abcs));
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    ContestWriter out = new ContestWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

