	public class FenwickTree : IEnumerable<long>
	{
		public static long InversionNumber(IReadOnlyList<int> numbers)
		{
			int n = numbers.Count;
			var bit = new FenwickTree(n);
			long ret = 0;
			for (int i = 0; i < n; i++) {
				ret += i - bit.Sum(numbers[i]);
				bit.Add(numbers[i], 1);
			}

			return ret;
		}

		private readonly int n_;
		private readonly long[] bit_;

		public FenwickTree(int count)
		{
			n_ = count;
			bit_ = new long[count + 1];
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public void Add(int index, long value)
		{
			++index;
			while (index <= n_) {
				bit_[index] += value;
				index += index & -index;
			}
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public long Sum(int index)
		{
			++index;
			long sum = 0;
			while (index > 0) {
				sum += bit_[index];
				index -= index & -index;
			}

			return sum;
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public long Sum(Range range) => Sum(range.Start.Value, range.End.Value);
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public long Sum(int l, int r) => Sum(r - 1) - Sum(l - 1);

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public int LowerBound(long w)
		{
			int m = n_ + 1;
			if (w <= 0) {
				return 0;
			} else {
				int x = 0;
				int r = 1;
				while (r < m) {
					r <<= 1;
				}

				for (int d = r; d > 0; d >>= 1) {
					if (x + d < m && bit_[x + d] < w) {
						w -= bit_[x + d];
						x += d;
					}
				}

				return x;
			}
		}

		System.Collections.IEnumerator System.Collections.IEnumerable.GetEnumerator() => GetEnumerator();
		public IEnumerator<long> GetEnumerator()
		{
			for (int i = 0; i < n_; i++) {
				yield return Sum(i);
			}
		}
	}

