        public static void Solve(Input input)
        {
            var n = input.NextInt();
            var q = input.NextInt();

            var rsq = new RangeSumQuery(n);
            var nn = input.NextInt(n);
            for (int i = 0; i < n; i++)
            {
                rsq.Add(i + 1, nn[i]);
            }

            for (int i = 0; i < q; i++)
            {
                var query = input.NextInt(3);
                if (query[0] == 0)
                {
                    rsq.Add(query[1] + 1, query[2]);
                }
                else
                {
                    Console.WriteLine(rsq.Sum(query[1] + 1, query[2]));
                }
            }
        }

        /// <summary>
        /// 区間内総和
        /// Binary Indexed Tree(BIT)による
        /// </summary>
        public class RangeSumQuery
        {
            private readonly int[] _data;

            /// <summary>
            /// 
            /// </summary>
            /// <param name="n">節点数</param>
            /// <param name="v">ノードの初期値</param>
            public RangeSumQuery(int n, int v = 0)
            {
                _data = Enumerable.Repeat(v, n + 1).ToArray();
            }

            /// <summary>
            /// 
            /// </summary>
            /// <param name="k">index(1-based)</param>
            /// <param name="v">加算する値</param>
            public void Add(int k, int v)
            {
                while (k < _data.Length)
                {
                    _data[k] += v;
                    k += k & -k;
                }
            }

            /// <summary>
            /// [0,k)の総和
            /// </summary>
            /// <param name="k">index(1-based)</param>
            /// <returns></returns>
            public long Sum(int k)
            {
                long sum = 0;
                while (k > 0)
                {
                    sum += _data[k];
                    k -= k & -k;
                }

                return sum;
            }

            /// <summary>
            /// [a,b)の総和
            /// [a]+[a+1]+...[r-1]
            /// </summary>
            /// <param name="l"></param>
            /// <param name="r"></param>
            /// <returns></returns>
            public long Sum(int l, int r)
            {
                var suma = Sum(l - 1);
                var sumb = Sum(r);

                return sumb - suma;
            }
        }

