    public void Solve()
    {
        var sc = new Scanner();
        int n = sc.NextInt();

        int q = sc.NextInt();
        int[] a = sc.IntArray();

        FenwickTree ft = new FenwickTree(n);
        for (int i = 0; i < n; i++)
        {
            ft.Add(i, a[i]);
        }

        Console.SetOut(new System.IO.StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false });
        for (int i = 0; i < q; i++)
        {
