	public class Scanner : IDisposable
	{
		private readonly char[] delimiter_ = new char[] { ' ' };
		private readonly string filePath_;
		private readonly StreamReader sr_;
		private string[] buf_;
		private int index_;

		public Scanner(string file = "")
		{
			if (string.IsNullOrWhiteSpace(file)) {
				sr_ = new StreamReader(Console.OpenStandardInput());
			} else {
				filePath_ = file;
				sr_ = new StreamReader(file);
			}

			Console.SetOut(new StreamWriter(Console.OpenStandardOutput()) {
				AutoFlush = false 
			});
			buf_ = new string[0];
			index_ = 0;
		}

		public void Dispose()
		{
			Console.Out.Flush();
			sr_.Dispose();
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public string NextLine() => sr_.ReadLine();
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public string Next()
		{
			if (index_ < buf_.Length) {
				return buf_[index_++];
			}

			string st = sr_.ReadLine();
			while (st == "") {
