public class BinaryIndexedTree {
	private long[] data;
	private int max;

	public BinaryIndexedTree(long size) { 
		data = new long[++size]; 
		max = 1;
        while ((max << 1) < data.Length) max <<= 1;
	}
	public void Add(long k, long v) { for(int i = (int)k+1; i < data.Length; i += i & -i) data[i] = data[i] + v; }
	public long Sum(long k) {
		if(k<0) return 0;
		long ret = 0;
		for(int i = (int)k+1; i > 0; i -= i & -i) ret = ret + data[i];
		return ret;
	}
	public long Sum(long l, long r) => Sum(r-1) - Sum(l-1);	// [l, r)
    public long LowerBound(long w) {
		if (w <= 0) return 0;
		int x = 0;
		for (int k = max; k > 0; k >>= 1) {
			if (x + k < data.Length && data[x + k] < w) {
				w = w - data[x + k];
				x = x + k;
			}
		}
		return x;
    }

}












