public class BIT
{
    //1-indexed
    int bit;
    long[] dat;
    public BIT(int N)
    {
        dat = new long[N + 1];
        bit = 1;
        while ((bit << 1) <= N) bit <<= 1;
    }
    public long this[int idx]
    {
        get { long s = 0; for (var i = idx; i > 0; i -= i & -i) s += dat[i]; return s; }
    }
    public void add(int idx, long v)
    {
        for (var i = idx; i < dat.Length; i += i & -i) dat[i] += v;
    }
    public int LowerBound(long v)
    {
        int now = 0;
        for (int k = bit; k > 0; k >>= 1)
        {
            if (now + k < dat.Length && dat[now + k] < v)
            {
                v -= dat[now + k];
                now += k;
            }
        }
        return now + 1;
    }
    public int UpperBound(long v)
    {
        int now = 0;
        for (int k = bit; k > 0; k >>= 1)
        {
            if (now + k < dat.Length && dat[now + k] <= v)
            {
                v -= dat[now + k];
                now += k;
            }
        }
        return now + 1;
    }
}

public class FastScanner
{
    //0x0a:LF 0x20:SPC 0x2d:- 0x30 ~ 0x39: 0 ~ 9
    static System.IO.Stream str = System.Console.OpenStandardInput();
    const int size = 1 << 10;
    static byte[] buffer = new byte[size];
    static int ptr;
    static int len;
    public int Int
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    public long Long
    {
        get
        {
            var c = Read();
            while (c < 0x21)
            {
                c = Read();
            }
            var n = false;
            if (c == '-')
            {
                n = true;
                c = Read();
            }
            var ret = 0L;
            while (c >= 0x30)
            {
                ret = ret * 10 + (c & 15);
                c = Read();
            }
            return n ? -ret : ret;
        }
    }
    byte Read()
    {
        if (ptr == len)
        {
            len = str.Read(buffer, 0, size);
            if (len == 0) return 0;
            ptr = 0;
        }
        return buffer[ptr++];
    }
}

