class Program
{
    static void Main(string[] args)
    {
        int n, q;
        var line = Console.ReadLine().Split();
        n = int.Parse(line[0]);
        q = int.Parse(line[1]);

        var fw = new LongFenwickTree(n);
        line = Console.ReadLine().Split();
        int[] a = line.Select(int.Parse).ToArray();
        for (int i = 0; i < a.Length; i++)
        {
            fw.Add(i, a[i]);
        }

        for (int i = 0; i < q; i++)
        {
            var query = Console.ReadLine().Split().Select(int.Parse).ToArray();
            if (query[0] == 0)
            {
                fw.Add(query[1], query[2]);
            }
            else
            {
                Console.WriteLine(fw.Sum(query[1], query[2]));
            }
        }
    }
}

