class BitIndexedTree
    attr_accessor:bit,:n
    def initialize(n,init_array=nil)
      @n=n
      @bit=Array.new(@n+1){0}
      unless init_array.nil?
        @n.times do|i|
            add(i+1,init_array[i])
        end
      end
    end

    def add(i,x)
        while i<=@n
            @bit[i]+=x
            i+=i&-i
        end
    end

    def sum(i)
        ret_sum=0
        while i>0
          ret_sum+=@bit[i]
          i-=i&-i
        end
        return ret_sum
    end

    def get_sum(l,r)
        return sum(r)-sum(l-1)
    end
end


