package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func configure(scanner *bufio.Scanner) {
	scanner.Split(bufio.ScanWords)
	scanner.Buffer(make([]byte, 1000005), 1000005)
}
func getNextString(scanner *bufio.Scanner) string {
	scanned := scanner.Scan()
	if !scanned {
		panic("scan failed")
	}
	return scanner.Text()
}
func getNextInt(scanner *bufio.Scanner) int {
	i, _ := strconv.Atoi(getNextString(scanner))
	return i
}
func getNextInt64(scanner *bufio.Scanner) int64 {
	i, _ := strconv.ParseInt(getNextString(scanner), 10, 64)
	return i
}
func getNextFloat64(scanner *bufio.Scanner) float64 {
	i, _ := strconv.ParseFloat(getNextString(scanner), 64)
	return i
}
func main() {
	fp := os.Stdin
	wfp := os.Stdout
	extra := 0
	if os.Getenv("I") == "IronMan" {
		fp, _ = os.Open(os.Getenv("END_GAME"))
		extra = 100
	}
	scanner := bufio.NewScanner(fp)
	configure(scanner)
	writer := bufio.NewWriter(wfp)
	defer func() {
		r := recover()
		if r != nil {
			fmt.Fprintln(writer, r)
		}
		writer.Flush()
	}()
	solve(scanner, writer)
	for i := 0; i < extra; i++ {
		fmt.Fprintln(writer, "-----------------------------------")
		solve(scanner, writer)
	}
}
func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	q := getNextInt(scanner)
	f := NewFenwickTree64(n)
	for i := 0; i < n; i++ {
		f.Add(i, getNextInt64(scanner))
	}
	for q > 0 {
		q--
		t := getNextInt(scanner)
		if t == 0 {
			f.Add(getNextInt(scanner), getNextInt64(scanner))
			continue
		}
		fmt.Fprintln(writer, f.Sum(getNextInt(scanner), getNextInt(scanner)))
	}
}

// FenwickTree Data structure that can efficiently update elements and calculate prefix sums in a table of numbers.
type FenwickTree struct {
	tree *FenwickTree64
}

// NewFenwickTree Constructor
func NewFenwickTree(n int) *FenwickTree {
	return &FenwickTree{tree: NewFenwickTree64(n)}
}

// Add processes a[p] += x.
func (f *FenwickTree) Add(p int, x int) {
	f.tree.Add(p, int64(x))
}

// Sum returns a[l] + a[l - 1] + ... + a[r - 1].
func (f *FenwickTree) Sum(l, r int) int {
	return int(f.tree.Sum(l, r))
}

// FenwickTree64 Data structure that can efficiently update elements and calculate prefix sums in a table of numbers.
type FenwickTree64 struct {
	n    int
	data []int64
}

// NewFenwickTree64 Constructor
func NewFenwickTree64(n int) *FenwickTree64 {
	data := make([]int64, n+1)
	return &FenwickTree64{n: n, data: data}
}

// Add processes a[p] += x.
func (f *FenwickTree64) Add(p int, x int64) {
	for p++; p <= f.n; p += p & -p {
		f.data[p] += x
	}
}

// Sum returns a[l] + a[l - 1] + ... + a[r - 1].
func (f *FenwickTree64) Sum(l, r int) int64 {
	return f.sum(r) - f.sum(l)
}
func (f *FenwickTree64) sum(r int) int64 {
	s := int64(0)
	for ; r > 0; r -= r & -r {
		s += f.data[r]
	}
	return s
}

