// BIT represents the Binary Indexed Tree
type BIT struct {
	a []int
}

// NewBIT returns the pointer to a BIT for the slice.
func NewBIT(a []int) *BIT {
	b := &BIT{
		a: make([]int, len(a)+1),
	}

	copy(b.a[1:], a)
	for d, ok := 2, true; ok; d *= 2 {
		ok = false
		for i := d; i < len(b.a); i += d {
			b.a[i] += b.a[i-d/2]
			ok = true
		}
	}
	return b
}

// Sum0N returns the sum of [0, n)
func (b *BIT) Sum0N(n int) int {
	var res int
	for i := n; 0 < i; i = i - i&(-i) {
		res += b.a[i]
	}
	return res
}

// Sum0N returns the sum of the range [i, j)
func (b *BIT) Sum(i, j int) int {
	return b.Sum0N(j) - b.Sum0N(i)
}

// Add updates the value at index i adding the diff.
func (b *BIT) Add(i int, diff int) {
	for j := i + 1; j < len(b.a); j = j + j&(-j) {
		b.a[j] += diff
	}
}

// Update updates the value at index i.
func (b *BIT) Update(i int, v int) {
	prev := b.Sum(i, i+1)
	diff := v - prev
	b.Add(i, diff)
}

