// BIT represents the Binary Indexed Tree
type FenwickTreeInt struct {
	n    int
	data []int
}

// NewBIT returns the pointer to a FenwickTree for the slice.
func NewFenwickTree(n int) *FenwickTreeInt {
	ft := &FenwickTreeInt{
		n:    n,
		data: make([]int, n),
	}

	return ft
}

func (ft *FenwickTreeInt) assert(exp bool) {
	if exp {
		return
	}

	pc, file, line, ok := runtime.Caller(1)
	if !ok {
		panic("ASSERT!: unknown position")
	}
	msg := fmt.Sprintf("ASSERT!: @0x%x %s[%d]", pc, file, line)
	panic(msg)
}

func (ft *FenwickTreeInt) sum(r int) int {
	var s int
	for r > 0 {
		s += ft.data[r-1]
		r -= r & -r
	}
	return s
}

func (ft *FenwickTreeInt) Sum(l, r int) int {
	ft.assert(0 <= l && l <= r && r <= ft.n)
	return ft.sum(r) - ft.sum(l)
}

func (ft *FenwickTreeInt) Add(p int, x int) {
	ft.assert(0 <= p && p < ft.n)
	p++
	for p <= ft.n {
		ft.data[p-1] += x
		p += p & -p
	}
}

