import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

var sc = bufio.NewScanner(os.Stdin)

func nextInt() int {
	sc.Scan()
	i, e := strconv.Atoi(sc.Text())
	if e != nil {
		panic(e)
	}
	return i
}

func nextFloat64() float64 {
	sc.Scan()
	i, e := strconv.ParseFloat(sc.Text(), 64)
	if e != nil {
		panic(e)
	}
	return i
}

func nextString() string {
	sc.Scan()
	return sc.Text()
}

func main() {
	sc.Split(bufio.ScanWords)

	n, q := nextInt(), nextInt()

	sums := make([]int, n)

	for i := 0; i < n; i++ {
		n := nextInt()
		if i > 0 {
			sums[i] = n + sums[i-1]
		} else {
			sums[i] = n
		}
	}

	for i := 0; i < q; i++ {
		t, v1, v2 := nextInt(), nextInt(), nextInt()
		if t == 0 {
			for j := v1; j < n; j++ {
				sums[j] += v2
			}
		} else {
			var left int = 0
			if v1 > 0 {
				left = sums[v1-1]
			}
			originSum := sums[v2-1] - left
			fmt.Println(originSum)
		}
	}
}

