var DEBUG = true

var cpuprofile = flag.String("cpuprofile", "", "write cpu profile")

func main() {
	flag.Parse()

	if *cpuprofile != "" {
		f, err := os.Create(*cpuprofile)
		if err != nil {
			log.Fatal(err)
		}
		pprof.StartCPUProfile(f)
		defer pprof.StopCPUProfile()
	}

	defer Flush()
	N := readi()
	Q := readi()

	z := U(0)

	b := NewFenwickTree(N, &z)
	for i := 0; i < N; i++ {
		v := readi()
		u := U(v)
		b.Add(i, &u)
	}
	for q := 0; q < Q; q++ {
		t := readi()
		x := readi()
		y := readi()
		if t == 0 {
			add(b, x, y)
		} else {
			println(sum(b, x, y))
		}
	}

}

func add(ft *FenwickTree, p, x int) {
	u := U(x)
	ft.Add(p, &u)
}

func sum(ft *FenwickTree, l, r int) int {
	v := ft.Sum(l, r).(*U)
	return int(*v)
}

type U int

func (u *U) Add(x FenwickTreeUnit) {
	ux := x.(*U)
	*u = *u + *ux
}

func (u *U) Sub(x FenwickTreeUnit) {
	ux := x.(*U)
	*u = *u - *ux
}

func (u *U) Clone() FenwickTreeUnit {
	r := *u
	return &r
}

type FenwickTreeUnit interface {
	Add(x FenwickTreeUnit)
	Sub(x FenwickTreeUnit)
	Clone() FenwickTreeUnit
}

// BIT represents the Binary Indexed Tree
type FenwickTree struct {
	n    int
	data []FenwickTreeUnit
	z    FenwickTreeUnit
}

// NewBIT returns the pointer to a FenwickTree for the slice.
func NewFenwickTree(n int, zeroValue FenwickTreeUnit) *FenwickTree {
	ft := &FenwickTree{
		n:    n,
		data: make([]FenwickTreeUnit, n),
		z:    zeroValue,
	}

	for i := range ft.data {
		ft.data[i] = ft.z.Clone()
	}

	return ft
}

func (ft *FenwickTree) assert(exp bool) {
	if exp {
		return
	}

	pc, file, line, ok := runtime.Caller(1)
	if !ok {
		panic("ASSERT!: unknown position")
	}
	msg := fmt.Sprintf("ASSERT!: @0x%x %s[%d]", pc, file, line)
	panic(msg)
}

func (ft *FenwickTree) sum(r int) FenwickTreeUnit {
	s := ft.z.Clone()
	for r > 0 {
		s.Add(ft.data[r-1])
		r -= r & -r
	}
	return s
}

func (ft *FenwickTree) Sum(l, r int) FenwickTreeUnit {
	ft.assert(0 <= l && l <= r && r <= ft.n)
	x := ft.sum(r)
	x.Sub(ft.sum(l))
	return x
}

func (ft *FenwickTree) Add(p int, x FenwickTreeUnit) {
	ft.assert(0 <= p && p < ft.n)
	p++
	for p <= ft.n {
		ft.data[p-1].Add(x)
		p += p & -p
	}
}

