type U int

func (u U) Add(x FenwickTreeUnit) FenwickTreeUnit {
	return u + x.(U)
}

func (u U) Sub(x FenwickTreeUnit) FenwickTreeUnit {
	return u - x.(U)
}

type FenwickTreeUnit interface {
	Add(x FenwickTreeUnit) FenwickTreeUnit
	Sub(x FenwickTreeUnit) FenwickTreeUnit
}

// BIT represents the Binary Indexed Tree
type FenwickTree struct {
	n    int
	data []FenwickTreeUnit
	z    FenwickTreeUnit
}

// NewBIT returns the pointer to a FenwickTree for the slice.
func NewFenwickTree(n int, zeroValue FenwickTreeUnit) *FenwickTree {
	ft := &FenwickTree{
		n:    n,
		data: make([]FenwickTreeUnit, n),
		z:    zeroValue,
	}

	for i := range ft.data {
		ft.data[i] = ft.z
	}

	return ft
}

func (ft *FenwickTree) assert(exp bool) {
	if exp {
		return
	}

	pc, file, line, ok := runtime.Caller(1)
	if !ok {
		panic("ASSERT!: unknown position")
	}
	msg := fmt.Sprintf("ASSERT!: @0x%x %s[%d]", pc, file, line)
	panic(msg)
}

func (ft *FenwickTree) sum(r int) FenwickTreeUnit {
	s := ft.z
	for r > 0 {
		s = s.Add(ft.data[r-1])
		r -= r & -r
	}
	return s
}

func (ft *FenwickTree) Sum(l, r int) FenwickTreeUnit {
	ft.assert(0 <= l && l <= r && r <= ft.n)
	return ft.sum(r).Sub(ft.sum(l))
}

func (ft *FenwickTree) Add(p int, x FenwickTreeUnit) {
	ft.assert(0 <= p && p < ft.n)
	p++
	for p <= ft.n {
		ft.data[p-1] = ft.data[p-1].Add(x)
		p += p & -p
	}
}

