template FenwickTree(T) {
  import std.traits : isSigned, Unsigned;

  static if (isSigned!T) {
    alias U = Unsigned!T;
  } else {
    alias U = T;
  }

  struct FenwickTree {

  private:
    long _n;
    U[] data;

  public:
    this(long n) {
      _n = n;
      data = new U[n];
    }

    void add(long p, T x)
    in (0 <= p && p < _n) {
      p++;
      while (p <= _n) {
        data[p - 1] += U(x);
        p += p & -p;
      }
    }

    T sum(long l, long r)
    in (0 <= l && l <= r && r <= _n) {
      return sum(r) - sum(l);
    }

  private:
    U sum(long r) {
      U s = 0;
      while (r > 0) {
        s += data[r - 1];
        r -= r & -r;
      }
      return s;
    }
  }
}

