/*
セグメント木 区分木 segtree segment tree
1点に書き込み、範囲で読み出す。
たとえば [l, r) の最大値を求めるなど。
引数
a, b　添字の範囲。 この意味はa から b - 1 までなので注意。
marge　左の子と右の子から自分の値をきめる関数（たとえばmax）
neutral　すべての x に対して marge(x, z) = x をみたすz（たとえば-infty）
*/
class SegTree(T){
	T value;
	T neutral;
	SegTree left, right; // 左の子(a <= x < c)、右の子(c <= x < b)
	bool hasValue;
	bool isTerminal;
	int a, b; // a <= x < b を担当する
	T delegate(T, T) marge;
	this(int a, int b, T delegate(T, T) marge, T neutral = T.init){
		this.a = a, this.b = b;
		this.marge = marge;
		this.neutral = neutral;
		if(b - a == 1){
			this.isTerminal = 1;
		}
		else{
			int c = (a + b) / 2;
			this.left = new SegTree(a, c, marge, neutral);
			this.right = new SegTree(c, b, marge, neutral);
		}
	}

	// [a, b) における値を読む ※[a, b) はこのノードの担当区間とかぶっていなくてもよい
	T getValue(int a, int b){
		if(b <= this.a || this.b <= a) return neutral;
		if(a <= this.a && this.b <= b){
			if(! this.hasValue){
				T v1 = this.left.getValue(a, b), v2 = this.right.getValue(a, b);
				T v = marge(v1, v2);
				this.value = v;
				this.hasValue = 1;
			}
			return this.value;
		}
		else{
			T v1 = this.left.getValue(a, b), v2 = this.right.getValue(a, b);
			T v = marge(v1, v2);
			return v;
		}
	}


	// i における値を設定
	void setValue(int i, T value){
		assert(a <= i && i < b);
		this.hasValue = 0; // これが漏れていた！！
		if(this.isTerminal){
			this.hasValue = 1;
			this.value = value;
		}
		else if(i < left.b) left.setValue(i, value);
		else right.setValue(i, value);
	}

	// 配列に変換したもの（デバッグ用）
	T[] array(){
		if(this.isTerminal) return [this.value];
		else return this.left.array ~ this.right.array;
	}

	// 文字列に変換したもの（デバッグ用）
	override string toString(){
		return this.array.to!string;
	}
}

