class FenwickTree:
    def __init__(self, arg):
        if isinstance(arg, int):
            self._n = arg
            self._a = [0] * arg
        elif isinstance(arg, Iterable):
            a = list(arg)
            self._n = len(a)
            self._a = [0] * self._n
            self.set(a)

    def set(self, a):
        for i, ai in enumerate(a):
            self.add(i, ai)

    def add(self, i, x):
        i += 1
        while i <= self._n:
            self._a[i - 1] += x
            i += i & -i

    def update(self, i, x):
        self.add(i, x - self.sum(i, i + 1))

    def sum(self, l, r):
        return self._sum(r) - self._sum(l)

    def _sum(self, r):
        s = 0
        while r > 0:
            s += self._a[r - 1]
            r -= r & -r
        return s


