    fn add(&mut self, pos: usize, value: usize) {
        let mut x = pos as isize;
        while x <= self.n {
            self.value[x as usize - 1] += value;
            x += x & -x;
        }
    }

    fn get(&self, pos: usize) -> usize {
        let mut sum = 0;
        let mut x = pos as isize;
        while x > 0 {
            sum += self.value[x as usize - 1];
            x -= x & -x;
        }
        sum
    }

    // 1-indexed, [l,r]
    fn sum(&self, l: usize, r: usize) -> usize {
        self.get(r) - self.get(l - 1)
    }
}

