pub mod atcoder_fenwicktree {
    use std::ops::{AddAssign, Sub};

    pub struct FenwickTree<T> {
        n: usize,
        data: Vec<T>,
    }

    impl<T: From<bool> + Clone + Copy + AddAssign<T> + Sub<T, Output = T>> FenwickTree<T> {
        pub fn new(n: usize) -> FenwickTree<T> {
            FenwickTree::<T> {
                n,
                data: vec![T::from(false); n],
            }
        }

        pub fn add(&mut self, i: usize, x: T) {
            assert!(i < self.n);
            let mut i = i + 1;
            while i <= self.n {
                self.data[i - 1] += x;
                i += i & !(i - 1);
            }
        }

        pub fn sum(&self, l: usize, r: usize) -> T {
            assert!(l <= r);
            assert!(r <= self.n);
            self.sum_internal(r) - self.sum_internal(l)
        }

        fn sum_internal(&self, r: usize) -> T {
            let mut r = r;
            let mut s = T::from(false);
            while r > 0 {
                s += self.data[r - 1];
                r -= r & !(r - 1);
            }
            s
        }
    }
}

