struct FenwickTree<T> {
    v: Vec<T>,
}

use std::ops::AddAssign;
use num::{Integer, zero};

impl<T: Copy + AddAssign + Integer> FenwickTree<T> {
    fn new(n: usize) -> Self {
        Self {
            v: vec![zero(); n],
        }
    }

    fn from_vec(v: Vec<T>) -> Self {
        let n = v.len();
        let mut t = Self::new(n);
        for i in 0..n {
            let v = t.v[i] + v[i];
            t.v[i] = v;
            let p = i + Self::lsb(i + 1);
            if p < n {
                t.v[p] += v;
            }
        }
        t
    }

    fn add(&mut self, mut i: usize, v: T) {
        while i < self.v.len() {
            self.v[i] += v;
            i += Self::lsb(i + 1);
        }
    }

    fn sum(&self, l: usize, r: usize) -> T {
        assert!(l <= r && r <= self.v.len());

        self.get(r) - self.get(l)
    }

    fn get(&self, mut i: usize) -> T {
        let mut v = zero();
        while i > 0 {
            v += self.v[i - 1];
            i -= Self::lsb(i);
        }
        v
    }

    fn lsb(i: usize) -> usize {
        i & i.wrapping_neg()
    }
}

use proconio::input;
fn main() {
    input! {
        n: usize,
        q: usize,
        a: [u32;n],
        qs: [(usize,usize,usize);q],
    }
    let mut ft=vec![0;n+1];
    for (i,a) in a.into_iter().enumerate() {
        add(&mut ft, i, a as u64);
    }
    for q in qs {
        if q.0==0 {
            add(&mut ft, q.1, q.2 as u64);
        }
        else {
            println!("{}",sum(&mut ft, q.2)-sum(&mut ft, q.1));
        }
    }
}
fn add(ft: &mut Vec<u64>, p: usize, x: u64) {
    let n=ft.len();
    let mut p=p+1;
    while p<n {
        ft[p]+=x;
        p+=p&p.wrapping_neg();
    }
}
fn sum(ft: &mut Vec<u64>, p: usize) -> u64 {
    let mut x=0;
    let mut p=p;
    while p>0 {
        x+=ft[p];
        p-=p&p.wrapping_neg();
    }
    x
}

