struct FenwikTree {
    size: usize,
    depth: usize,
    tree: Vec<i64>,
}
impl FenwikTree {
    fn new(n: usize) -> Self {
        let size = n;
        let mut v = size;
        let mut tmp = 0;
        while v > 0 {
            tmp += 1;
            v >>= 1
        }
        let depth = tmp;
        let tree = vec![0; size + 1];
        FenwikTree { size, depth, tree }
    }
    fn _bitsum(&self, mut i: usize) -> i64 {
        let mut ret = 0;
        while i > 0 {
            ret += self.tree[i];
            i ^= i & (1 + !i);
        }
        ret
    }
    fn bitsum(&self, l: usize, r: usize) -> i64 {
        self._bitsum(r) - self._bitsum(l)
    }
    fn bitadd(&mut self, mut i: usize, x: i64) {
        i += 1;
        while i <= self.size {
            self.tree[i] += x;
            i += i & (1 + !i);
        }
    }
    fn lower_bound(&self, x: i64) -> usize {
        let mut _sum: i64 = 0;
        let mut pos: usize = 0;
        let mut v: usize = 1 << self.depth;
        for _ in (0..self.depth).rev() {
            let k = pos + v;
            if k <= self.size && _sum + self.tree[k] < x {
                _sum += self.tree[k];
                pos = k;
            }
            v >>= 1;
        }
        pos + 1
    }
}

#[fastout]
fn main() {
    input! {
        N: usize, Q: usize,
        a: [i64; N],
        l: [(usize, usize, usize); Q]
    }
    let mut bit = FenwikTree::new(N);
    for i in 0..N {
        bit.bitadd(i, a[i]);
    }
    for &(t, x, y) in &l {
        if t > 0 {
            println!("{}", bit.bitsum(x, y));
        } else {
            bit.bitadd(x, y as i64);
        }
    }
    // println!("{}", N);
}

