            r.r.consume(1);
            let s = r.r.fill_buf().unwrap()[0];
            assert!(s == b' ' || s == b'\n');
            r.r.consume(1);
            b
        }
    }

    macro_rules! cpin_tuple {
        ($($t:ident),*) => {
            impl<$($t: CpIn),*> CpIn for ($($t),*) {
                fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
                    ($($t::read_from(r)),*)
                }
            }
        };
    }

    macro_rules! cpin_cast {
        ($t_self:ty, $t_read:ty) => {
            impl CpIn for $t_self {
                fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
                    <$t_read>::read_from(r) as $t_self
                }
            }
        };
    }
    macro_rules! cpin_parse {
        ($t:ty) => {
            impl CpIn for $t {
                fn read_from<R: BufRead>(r: &mut CpReader<R>) -> Self {
                    r.read_word_str().parse().unwrap()
                }
            }
        };
    }
    cpin_cast!(usize, u64);
    cpin_cast!(u32, u64);
    cpin_cast!(u16, u64);
    cpin_cast!(i32, i64);
    cpin_cast!(i16, i64);
    cpin_cast!(i8, i64);

    cpin_parse!(f64);

    cpin_tuple!(T1, T2);
    cpin_tuple!(T1, T2, T3);
    cpin_tuple!(T1, T2, T3, T4);
    cpin_tuple!(T1, T2, T3, T4, T5);

    fn read_u64_fast<R: BufRead>(r: &mut R) -> u64 {
        let mut value = 0;
        loop {
            let buf = r.fill_buf().unwrap();
            assert!(!buf.is_empty());
            let mut idx = 0;
            while let Some(&c) = buf.get(idx) {
                if b'0' <= c && c <= b'9' {
                    value = value * 10 + (c - b'0') as u64;
                    idx += 1;
                } else {
                    r.consume(idx + 1);
                    return value;
                }
            }
            r.consume(idx);
        }
    }
    fn read_i64_fast<R: BufRead>(r: &mut R) -> i64 {
        let sign = match r.fill_buf().unwrap()[0] {
            b'+' => {
                r.consume(1);
                1
            }
            b'-' => {
                r.consume(1);
                -1
            }
            _ => 1,
        };
        read_u64_fast(r) as i64 * sign
    }
}

mod fenwick_tree {
    use num::{zero, Zero};
    use std::{
        fmt::Debug,
        ops::{AddAssign, Range, Sub},
    };

    #[derive(Debug)]
    pub struct FenwickTree<T> {
        data: Vec<T>,
    }

    impl<T: Zero + AddAssign + Sub<Output = T> + Copy + Debug> FenwickTree<T> {
        #[inline]
        pub fn new(len: usize) -> Self {
            Self {
                data: vec![zero(); len],
            }
        }
        #[inline]
        pub fn from_iter(source: impl Iterator<Item = T> + ExactSizeIterator) -> Self {
            let len = source.len();
            let mut data = vec![zero(); len];
            let mut idx = 0;
            for value in source {
                data[idx] += value;
                let idx_parent = idx + Self::len_of(idx + 1);
                if idx_parent < data.len() {
                    let value = data[idx];
                    data[idx_parent] += value;
                }
                idx += 1;
            }
            Self { data }
        }

        #[inline]
        pub fn add(&mut self, index: usize, value: T) {
            let mut p = index + 1;
            while p <= self.data.len() {
                self.data[p - 1] += value;
                p += Self::len_of(p);
            }
        }

        #[inline]
        pub fn sum(&self, range: Range<usize>) -> T {
            self.leading_sum(range.end) - self.leading_sum(range.start)
        }

        #[inline]
        fn leading_sum(&self, index: usize) -> T {
            let mut s = zero();
            let mut r = index;
            while r > 0 {
                s += self.data[r - 1];
                r -= Self::len_of(r);
            }
            s
        }

        #[inline]
        fn len_of(p: usize) -> usize {
            p & p.wrapping_neg()
        }
    }
}

