struct FenwickTree<T> {
    n: usize,
    v: Vec<T>,
}

use std::ops::AddAssign;
use num::{Integer, zero};
impl<T: Copy + Integer + AddAssign> FenwickTree<T> {
    fn new(n: usize) -> Self {
        Self {
            n,
            v: vec![zero(); n],
        }
    }

    fn add(&mut self, i: usize, v: T) {
        let mut i = i + 1;
        while i <= self.n {
            self.v[i - 1] += v;
            i += i & i.wrapping_neg();
        }
    }

    fn sum(&self, l: usize, r: usize) -> T {
        self.get(r) - self.get(l)
    }

    fn get(&self, mut i: usize) -> T {
        let mut v = zero();
        while i > 0 {
            v += self.v[i - 1];
            i -= i & i.wrapping_neg();
        }
        v
    }
}

