}

impl FenwickTree {
    fn new(n: usize) -> Self {
        Self {
            n,
            value: vec![0; n],
        }
    }
    fn add(&mut self, mut pos: usize, value: usize) {
        while pos <= self.n {
            self.value[pos - 1] += value;
            pos += pos & (-(pos as isize) as usize);
        }
    }

    fn get(&self, mut pos: usize) -> usize {
        let mut sum = 0;
        while pos > 0 {
            sum += self.value[pos - 1];
            pos -= pos & (-(pos as isize) as usize);
        }
        sum
    }

    // 1-indexed, [l,r]
    fn sum(&self, l: usize, r: usize) -> usize {
        self.get(r) - self.get(l - 1)
    }
}

