#[derive(Debug)]
pub struct FenwickTree<T> {
    n: usize,
    data: Vec<T>,
}

impl<T> FenwickTree<T>
where
    T: AddAssign + Sub<Output = T> + Clone + Copy + Default,
{
    pub fn new(n: usize) -> Self {
        FenwickTree {
            n,
            data: vec![T::default(); n],
        }
    }

    pub fn add(&mut self, p: usize, x: T) {
        assert!(p < self.n);
        let mut p = p as isize;
        p += 1;
        while p <= self.n as isize {
            self.data[(p - 1) as usize] += x;
            p += p & -p;
        }
    }

    pub fn sum(&self, l: usize, r: usize) -> T {
        assert!(l <= r && r <= self.n);
        self._sum(r) - self._sum(l)
    }

    fn _sum(&self, r: usize) -> T {
        let mut s = T::default();
        let mut r = r as isize;
        while r > 0 {
            s += self.data[(r - 1) as usize];
            r -= r & -r;
        }
        s
    }
}

