where
    T: AddAssign + Sub<Output = T> + Clone + Copy + Default,
{
    fn from(v: Vec<T>) -> FenwickTree<T> {
        let n = v.len();
        let mut tree = FenwickTree::new(n);
        for (i, &e) in v.iter().enumerate() {
            tree.add(i, e);
        }
        tree
    }
}

