fn main() {
    input! {//
        n:usize,q:usize,
        a:[u64;n],
        q:[(usize,usize,usize);q],
    }

    let mut bt = BIT::<SUM>::new(3 * n + 10);
    let mut base = 5;
    for (i, &x) in a.iter().enumerate() {
        bt.add(i + base, &x);
    }
    for &(q, a, b) in q.iter() {
        if q == 1 {
