fn main() {
    let v = read_vec::<usize>();
    let (n, q) = (v[0], v[1]);
    let a = read_vec::<i64>();

    let mut bit = BinaryIndexTree::new(n);
    for i in 0..n {
        bit.add(i + 1, a[i]);
    }
    for i in 0..q {
        let query = read_vec::<i64>();
        if query[0] == 0 {
            let (p, x) = (query[1] as usize + 1, query[2]);
            bit.add(p + 1, x);
        } else {
            let (l, r) = (query[1] as usize, query[2] as usize);
            let ans;
            if l > 0 {
                ans = bit.sum(r) - bit.sum(l);
            } else {
                ans = bit.sum(r);
            }
            println!("{}", ans);
        }
    }
}

struct BinaryIndexTree {
    bit: Vec<i64>,
    n: usize,
}

impl BinaryIndexTree {
    fn new(n: usize) -> BinaryIndexTree {
        BinaryIndexTree {
            bit: vec![0; n + 1],
            n: n,
        }
    }

    fn sum(&self, i: usize) -> i64 {
        assert!(i > 0);
        let mut i = i;
        let mut s = 0i64;
        while i > 0 {
            s += self.bit[i];
            i -= (i as i64 & -(i as i64)) as usize;
        }
        s
    }

    fn add(&mut self, i: usize, x: i64) {
        assert!(i > 0);
        let mut i = i;
        while i <= self.n {
            self.bit[i as usize] += x;
            i += (i as i64 & -(i as i64)) as usize;
        }
    }
}

fn read<T: std::str::FromStr>() -> T {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).ok();
    s.trim().parse().ok().unwrap()
}

fn read_vec<T: std::str::FromStr>() -> Vec<T> {
    read::<String>()
        .split_whitespace()
        .map(|e| e.parse().ok().unwrap())
        .collect()
}
